function readSettingJson<T>(settings: Record<string, string>, key: string, fallback: T): T {
  try { const parsed = JSON.parse(settings[key] || ''); return parsed as T; } catch { return fallback; }
}
const storeAccountsFrom = (settings: Record<string, string>) => readSettingJson<StoreAccount[]>(settings, 'store_accounts', DEFAULT_STORE_ACCOUNTS);
const rechargePackagesFrom = (settings: Record<string, string>) => {
  const raw = readSettingJson<Partial<RechargePackage>[]>(settings, 'store_recharge_packages', DEFAULT_RECHARGE_PACKAGES);
  if (!Array.isArray(raw) || raw.some(item => item.coins === undefined)) return DEFAULT_RECHARGE_PACKAGES;
  return raw.map(item => ({ ...item, coins: Number(item.coins), price: Number(item.price), amount: Number(item.amount ?? item.coins ?? 0), active: item.active !== false })) as RechargePackage[];
};
const liveSlotsFrom = (settings: Record<string, string>) => {
  const raw = readSettingJson<Partial<LiveSlot>[]>(settings, 'store_live_slots', DEFAULT_LIVE_SLOTS);
  if (!Array.isArray(raw)) return DEFAULT_LIVE_SLOTS;
  return raw.map((item, index) => ({
    ...DEFAULT_LIVE_SLOTS[index % DEFAULT_LIVE_SLOTS.length],
    ...item,
    id: String(item.id || `live-${index + 1}`),
    title: String(item.title || ''),
    subtitle: String(item.subtitle || ''),
    url: String(item.url || ''),
    type: item.type === 'LIVE' ? 'LIVE' : 'VIDEO',
    state: item.state === 'LIVE' || item.state === 'UPCOMING' || item.state === 'REPLAY' ? item.state : item.type === 'LIVE' ? 'UPCOMING' : 'REPLAY',
    provider: item.provider === 'DIRECT' ? 'DIRECT' : item.provider === 'YOUTUBE' ? 'YOUTUBE' : /\.(mp4|webm|ogg|m3u8)(\?.*)?$/i.test(String(item.url || '')) ? 'DIRECT' : 'YOUTUBE',
    thumbnail: String(item.thumbnail || ''),
  })) as LiveSlot[];
};
const buildLiveSchedule = (seed: number, tournaments: Tournament[]): LiveScheduleItem[] => {
  const first = tournaments[0]?.title || 'بطولة ARENA//X المفتوحة';
  const second = tournaments[1]?.title || 'كأس التحدي السريع';
  const at = (minutes: number, tournament?: Tournament) => {
    const stored = tournament?.start_at ? Date.parse(tournament.start_at) : NaN;
    return new Date(Number.isFinite(stored) ? stored : seed + minutes * 60 * 1000).toISOString();
  };
  return [
    { id: 'schedule-main', title: first, league: 'ARENA//X OPEN', platform: tournaments[0]?.platform || 'eFootball Mobile', startsAt: at(28, tournaments[0]), prize: tournaments[0] ? money(tournaments[0].prize_pool) : '$2,400', tone: 'green' },
    { id: 'schedule-cup', title: second, league: 'NIGHT CUP / WEEK 04', platform: tournaments[1]?.platform || 'PlayStation', startsAt: at(142, tournaments[1]), prize: tournaments[1] ? money(tournaments[1].prize_pool) : '$1,500', tone: 'blue' },
    { id: 'schedule-showdown', title: 'SHOWDOWN: المغرب ضد العالم', league: 'COMMUNITY SERIES', platform: 'Xbox / PC', startsAt: at(286), prize: '$900', tone: 'amber' },
  ];
};
