const newFeaturedMatch = (): FeaturedMatch => ({ id: `featured-${Date.now()}`, title: 'مواجهة جديدة', creatorName: 'لاعب 1', creatorShort: 'P1', creatorTeam: 'real-madrid', opponentName: 'لاعب 2', opponentShort: 'P2', opponentTeam: 'barcelona', prize: 180, note: 'ضمان مالي مفعّل', active: false });
const readFeaturedMatches = (settings: Record<string, string>): FeaturedMatch[] => {
  if (!settings.featured_matches) return DEFAULT_FEATURED_MATCHES;
  try {
    const parsed = JSON.parse(settings.featured_matches) as Partial<FeaturedMatch>[];
    if (!Array.isArray(parsed)) return DEFAULT_FEATURED_MATCHES;
    return parsed.map((item, index) => ({ ...newFeaturedMatch(), ...item, id: String(item.id || `featured-${index}`), prize: Number(item.prize || 0), active: Boolean(item.active) }));
  } catch { return DEFAULT_FEATURED_MATCHES; }
};

function useStored<T>(key: string, fallback: T): [T, (value: T | ((old: T) => T)) => void] {
  const [value, setValue] = useState<T>(() => {
    try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; } catch { return fallback; }
  });
  const update = (next: T | ((old: T) => T)) => setValue(current => typeof next === 'function' ? (next as (old: T) => T)(current) : next);
  useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]);
  return [value, update];
}

