function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const { login, register } = useArena(); const [, setLocation] = useLocation(); const isLogin = mode === 'login'; const [form, setForm] = useState({ login: '', password: '', username: '', email: '', efootball_id: '', whatsapp: '' }); const [error, setError] = useState('');
  const returnTo = new URLSearchParams(window.location.search).get('returnTo');
  const update = (key: keyof typeof form, value: string) => setForm(old => ({ ...old, [key]: value }));
  useEffect(() => { const subtitle = document.querySelector('.auth-card > p'); if (subtitle) subtitle.textContent = isLogin ? 'تابع مبارياتك وأدر رصيدك بأمان.' : 'انضم إلى مجتمع لاعبي eFootball من كل مكان.'; }, [isLogin]);
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (isLogin) {
      const role = await login(form.login, form.password);
      if (!role) return setError('بيانات الدخول غير صحيحة أو الحساب غير مؤكد.');
      setLocation(returnTo || (role === 'ADMIN' ? '/admin' : '/matches'));
      return;
    }
    const result = await register(form);
    if (!result) return setError('تعذر إنشاء الحساب. تحقق من البيانات أو أن البريد مستخدم مسبقاً.');
    if (result === 'CONFIRM_EMAIL') return setError('تم إنشاء الحساب. تحقق من بريدك الإلكتروني ثم سجّل الدخول.');
    setLocation(returnTo || '/matches');
  };
  return <div className="auth-page"><div className="auth-card"><span className="auth-mark">{isLogin ? <LogIn className="h-7 w-7" /> : <UserPlus className="h-7 w-7" />}</span><h1>{isLogin ? 'تسجيل الدخول' : 'إنشاء حساب جديد'}</h1><p>{isLogin ? 'تابع مبارياتك وأدر رصيدك بأمان.' : 'انضم إلى مجتمع لاعبي eFootball في المغرب.'}</p>{error && <Notice type="error">{error}</Notice>}<form onSubmit={submit} className="form-stack">{isLogin ? <><Field label="اسم المستخدم أو البريد الإلكتروني" value={form.login} onChange={value => update('login', value)} test="input-login" /><Field label="كلمة المرور" type="password" value={form.password} onChange={value => update('password', value)} test="input-password" /></> : <><div className="form-grid"><Field label="اسم المستخدم" value={form.username} onChange={value => update('username', value)} test="input-username" /><Field label="معرّف eFootball" value={form.efootball_id} onChange={value => update('efootball_id', value)} test="input-efootball-id" /></div><Field label="رقم واتساب" value={form.whatsapp} onChange={value => update('whatsapp', value)} test="input-whatsapp" /><Field label="البريد الإلكتروني" type="email" value={form.email} onChange={value => update('email', value)} test="input-email" /><Field label="كلمة المرور" type="password" value={form.password} onChange={value => update('password', value)} test="input-register-password" /></>}<button className="primary-button full" data-testid={`button-submit-${mode}`}>{isLogin ? 'دخول إلى الحساب' : 'إنشاء الحساب'}<ArrowLeft className="h-4 w-4" /></button></form><div className="auth-switch">{isLogin ? <>ليس لديك حساب؟ <Link href="/register">أنشئ حساباً مجاناً</Link></> : <>لديك حساب بالفعل؟ <Link href="/login">سجّل الدخول</Link></>}</div></div></div>;
}

  function LegacyRechargeModal({ onClose }: { onClose: () => void }) {
   const { user, recharge, settings, recharges } = useArena(); const [amount, setAmount] = useState('50'); const [method, setMethod] = useState('التحويل البنكي'); const [whatsapp, setWhatsapp] = useState(user?.whatsapp || ''); const [notes, setNotes] = useState(''); const [sent, setSent] = useState(false); const [error, setError] = useState(''); const quickAmounts = (settings.recharge_amounts || '5,10,20,50,100,200,500').split(',').map(item => Number(item.trim())).filter(item => item > 0);
   const submit = async (event: FormEvent) => { event.preventDefault(); const value = Number(amount); if (!value || value < 5) return setError('الحد الأدنى للشحن هو 5 دولارات.'); if (await recharge(value, method, whatsapp, notes)) setSent(true); else setError('تعذر حفظ طلب الشحن. حاول مرة أخرى.'); };
    return <Modal onClose={onClose} wide><div className="modal-heading"><span className="panel-icon green"><Wallet className="h-5 w-5" /></span><span><h2>شحن الرصيد</h2><p>أرسل طلب الشحن وستراجعه الإدارة يدوياً.</p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم إرسال الطلب</h3><p>سيظهر طلبك في سجل الشحن، وستتم إضافة الرصيد بعد المراجعة.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="payment-card"><p>بيانات التحويل</p><strong>{method === 'التحويل البنكي' ? settings.cih_name : settings.cashplus_name}</strong><span>{method === 'التحويل البنكي' ? settings.cih_rib : `Cash Plus • ${settings.cashplus_cin}`}</span></div><div className="quick-amounts"><span>اختر مبلغاً سريعاً</span><div>{quickAmounts.map(value => <button type="button" className={Number(amount) === value ? 'quick-amount active' : 'quick-amount'} onClick={() => setAmount(String(value))} key={value}>{money(value)}</button>)}</div></div><div className="form-grid"><Field label="المبلغ المطلوب ($)" type="number" value={amount} onChange={setAmount} test="input-recharge-amount" /><label className="form-field"><span>طريقة الدفع</span><select value={method} onChange={event => setMethod(event.target.value)}><option>التحويل البنكي</option><option>Cash Plus</option></select></label></div><Field label="رقم واتساب للتأكيد" value={whatsapp} onChange={setWhatsapp} test="input-recharge-whatsapp" /><label className="form-field"><span>ملاحظات إضافية</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={3} /></label><button className="primary-button full">إرسال طلب الشحن <ArrowLeft className="h-4 w-4" /></button></form>}<div className="modal-history"><strong>آخر طلباتك</strong>{recharges.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
}

  function LegacyWithdrawModal({ onClose }: { onClose: () => void }) {
  const { user, requestWithdrawal, withdrawals } = useArena(); const [amount, setAmount] = useState(''); const [method, setMethod] = useState('التحويل البنكي'); const [destination, setDestination] = useState(''); const [notes, setNotes] = useState(''); const [error, setError] = useState(''); const [sent, setSent] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); const okay = await requestWithdrawal(Number(amount), method, destination, notes); if (!okay) return setError('تعذر تسجيل طلب السحب. تحقق من المبلغ والرصيد ثم حاول مرة أخرى.'); setSent(true); };
   return <Modal onClose={onClose}><div className="modal-heading"><span className="panel-icon amber"><ArrowUpFromLine className="h-5 w-5" /></span><span><h2>طلب سحب</h2><p>الرصيد المتاح: <b>{money(user?.balance || 0)}</b></p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم تسجيل طلب السحب</h3><p>سيتم تحويل المبلغ بعد اعتماد الإدارة.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<Field label="المبلغ ($)" type="number" value={amount} onChange={setAmount} test="input-withdraw-amount" />{Number(amount) > 0 && <div className="fee-notice">عمولة السحب 5%: {money(Number(amount) * 0.05)} • الصافي المحوّل: {money(Number(amount) * 0.95)}</div>}<label className="form-field"><span>طريقة الاستلام</span><select value={method} onChange={event => setMethod(event.target.value)}><option>التحويل البنكي</option><option>Cash Plus</option></select></label><Field label="رقم الحساب أو الهاتف" value={destination} onChange={setDestination} test="input-withdraw-destination" /><label className="form-field"><span>ملاحظات</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={2} /></label><button className="primary-button full">إرسال طلب السحب</button></form>}<div className="modal-history"><strong>آخر طلبات السحب</strong>{withdrawals.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)} • صافي {money(item.payoutAmount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
 }

const fallbackPaymentMethods = (kind: PaymentMethod['kind'], settings: Record<string, string>): PaymentMethod[] => kind === 'RECHARGE' ? [
  { id: 'fallback-bank', kind, name: 'التحويل البنكي', details: `اسم المستفيد: ${settings.cih_name || 'إدارة ARENA//X'}\nRIB: ${settings.cih_rib || 'سيتم تحديده من الإدارة'}`, enabled: true, sort_order: 10 },
  { id: 'fallback-cashplus', kind, name: 'Cash Plus', details: `اسم المستفيد: ${settings.cashplus_name || 'إدارة ARENA//X'}\nرقم التعريف: ${settings.cashplus_cin || 'سيتم تحديده من الإدارة'}`, enabled: true, sort_order: 20 },
] : [
  { id: 'fallback-bank-withdrawal', kind, name: 'التحويل البنكي', details: 'سيتم التحويل إلى الحساب الذي تدخله في طلب السحب.', enabled: true, sort_order: 10 },
  { id: 'fallback-cashplus-withdrawal', kind, name: 'Cash Plus', details: 'سيتم التحويل إلى رقم الهاتف أو الحساب الذي تدخله في طلب السحب.', enabled: true, sort_order: 20 },
];
function RechargeModal({ onClose }: { onClose: () => void }) {
  const { user, recharge, settings, recharges, paymentMethods } = useArena(); const methods = paymentMethods.filter(item => item.kind === 'RECHARGE' && item.enabled).sort((a, b) => a.sort_order - b.sort_order); const options = methods.length ? methods : fallbackPaymentMethods('RECHARGE', settings); const [methodId, setMethodId] = useState(options[0]?.id || ''); const [amount, setAmount] = useState('50'); const [whatsapp, setWhatsapp] = useState(user?.whatsapp || ''); const [notes, setNotes] = useState(''); const [sent, setSent] = useState(false); const [error, setError] = useState(''); const selected = options.find(item => item.id === methodId) || options[0]; const quickAmounts = (settings.recharge_amounts || '5,10,20,50,100,200,500').split(',').map(item => Number(item.trim())).filter(item => item > 0); const submit = async (event: FormEvent) => { event.preventDefault(); const value = Number(amount); if (!value || value < 5 || !selected) return setError('اختر طريقة دفع ومبلغاً صحيحاً. الحد الأدنى للشحن هو 5 دولارات.'); if (await recharge(value, selected.name, whatsapp, notes)) setSent(true); else setError('تعذر حفظ طلب الشحن. حاول مرة أخرى.'); };
  return <Modal onClose={onClose} wide><div className="modal-heading"><span className="panel-icon green"><Wallet className="h-5 w-5" /></span><span><h2>شحن الرصيد</h2><p>اختر طريقة الدفع التي أضافتها الإدارة.</p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم إرسال الطلب</h3><p>ستراجع الإدارة طلب الشحن يدوياً.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="form-grid"><Field label="المبلغ المطلوب ($)" type="number" value={amount} onChange={setAmount} test="input-recharge-amount" /><label className="form-field"><span>طريقة الدفع</span><select value={methodId} onChange={event => setMethodId(event.target.value)}>{options.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label></div><div className="payment-card"><p>بيانات التحويل</p><strong>{selected?.name}</strong><span>{selected?.details}</span></div><div className="quick-amounts"><span>اختر مبلغاً سريعاً</span><div>{quickAmounts.map(value => <button type="button" className={Number(amount) === value ? 'quick-amount active' : 'quick-amount'} onClick={() => setAmount(String(value))} key={value}>{money(value)}</button>)}</div></div><Field label="رقم واتساب للتأكيد" value={whatsapp} onChange={setWhatsapp} test="input-recharge-whatsapp" /><label className="form-field"><span>ملاحظات إضافية</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={3} /></label><button className="primary-button full">إرسال طلب الشحن <ArrowLeft className="h-4 w-4" /></button></form>}<div className="modal-history"><strong>آخر طلباتك</strong>{recharges.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
}
function WithdrawModal({ onClose }: { onClose: () => void }) {
  const { user, requestWithdrawal, withdrawals, settings, paymentMethods } = useArena(); const methods = paymentMethods.filter(item => item.kind === 'WITHDRAWAL' && item.enabled).sort((a, b) => a.sort_order - b.sort_order); const options = methods.length ? methods : fallbackPaymentMethods('WITHDRAWAL', settings); const [methodId, setMethodId] = useState(options[0]?.id || ''); const [amount, setAmount] = useState(''); const [destination, setDestination] = useState(''); const [notes, setNotes] = useState(''); const [error, setError] = useState(''); const [sent, setSent] = useState(false); const selected = options.find(item => item.id === methodId) || options[0]; const submit = async (event: FormEvent) => { event.preventDefault(); const okay = await requestWithdrawal(Number(amount), selected?.name || '', destination, notes); if (!okay) return setError('تعذر تسجيل طلب السحب. تحقق من المبلغ والرصيد ثم حاول مرة أخرى.'); setSent(true); };
  return <Modal onClose={onClose}><div className="modal-heading"><span className="panel-icon amber"><ArrowUpFromLine className="h-5 w-5" /></span><span><h2>طلب سحب</h2><p>الرصيد المتاح: <b>{money(user?.balance || 0)}</b></p></span></div>{sent ? <div className="success-panel"><CheckCircle2 className="h-12 w-12" /><h3>تم تسجيل طلب السحب</h3><p>سيتم تحويل المبلغ بعد اعتماد الإدارة.</p><button className="primary-button" onClick={onClose}>حسناً</button></div> : <form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<Field label="المبلغ ($)" type="number" value={amount} onChange={setAmount} test="input-withdraw-amount" />{Number(amount) > 0 && <div className="fee-notice">عمولة السحب 5%: {money(Number(amount) * 0.05)} • الصافي المحوّل: {money(Number(amount) * 0.95)}</div>}<label className="form-field"><span>طريقة الاستلام</span><select value={methodId} onChange={event => setMethodId(event.target.value)}>{options.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><div className="payment-card"><p>معلومات الطريقة</p><span>{selected?.details}</span></div><Field label="رقم الحساب أو الهاتف" value={destination} onChange={setDestination} test="input-withdraw-destination" /><label className="form-field"><span>ملاحظات</span><textarea value={notes} onChange={event => setNotes(event.target.value)} rows={2} /></label><button className="primary-button full">إرسال طلب السحب</button></form>}<div className="modal-history"><strong>آخر طلبات السحب</strong>{withdrawals.filter(item => item.userId === user?.id).slice(0, 3).map(item => <div key={item.id}><span>#{item.id} • {money(item.amount)} • صافي {money(item.payoutAmount)}</span><StatusBadge status={item.status} /></div>)}</div></Modal>;
}

function CreateMatchModal({ onClose }: { onClose: () => void }) {
   const { user, createMatch } = useArena(); const [, setLocation] = useLocation(); const [title, setTitle] = useState(''); const [stake, setStake] = useState('20'); const [platform, setPlatform] = useState('الهاتف'); const [error, setError] = useState('');
   if (!canPlay(user)) return <Modal onClose={onClose}><div className="verification-callout"><ShieldCheck className="h-10 w-10" /><h2>فعّل حسابك أولاً</h2><p>بدء المباريات متاح بعد تأكيد رقم واتساب وإرسال بطاقة التعريف ومراجعتها من الإدارة.</p><button className="primary-button full" onClick={() => { onClose(); setLocation('/verify?returnTo=/matches'); }}>الانتقال إلى تفعيل الحساب <ArrowLeft className="h-4 w-4" /></button></div></Modal>;
     const submit = async (event: FormEvent) => { event.preventDefault(); if (!canPlay(user)) return setLocation('/verify?returnTo=/matches'); const value = Number(stake); const id = value >= 5 ? await createMatch(title, value, platform) : null; if (!id) return setError(value < 5 ? 'الحد الأدنى للمباراة هو 5 دولارات.' : 'تعذر إنشاء المباراة. تحقق من الرصيد ثم حاول مرة أخرى.'); onClose(); setLocation(`/matches/${id}`); };
   return <Modal onClose={onClose}><div className="modal-heading"><span className="panel-icon green"><Swords className="h-5 w-5" /></span><span><h2>إنشاء مباراة جديدة</h2><p>حدّد قيمة الرهان والمنصة ثم انتظر منافساً.</p></span></div><form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<Field label="عنوان المباراة" value={title} onChange={setTitle} placeholder="مثال: تحدٍّ سريع" /><div className="form-grid"><Field label="قيمة الرهان ($)" type="number" value={stake} onChange={setStake} /><label className="form-field"><span>المنصة</span><select value={platform} onChange={event => setPlatform(event.target.value)}><option>الهاتف</option><option>PlayStation</option><option>Xbox / PC</option></select></label></div><div className="summary-row"><span>الجائزة المتوقعة</span><strong>{money(Number(stake || 0) * 1.8)}</strong></div><button className="primary-button full">نشر التحدي <ArrowLeft className="h-4 w-4" /></button></form></Modal>;
}

function HomePage() {
  const { user, matches, tournaments, players, settings, onlineCount, joinMatch } = useArena();
  const [, setLocation] = useLocation();
  const [createOpen, setCreateOpen] = useState(false);
  const [rechargeOpen, setRechargeOpen] = useState(false);
  const openMatchCount = matches.filter(item => item.status === 'OPEN').length;
  const openMatches = matches.filter(item => item.status === 'OPEN').sort((a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime()).slice(0, 3);
  const rankedPlayers = rankPlayers(players).slice(0, 3);
  const featured = readFeaturedMatches(settings).find(item => item.active) || readFeaturedMatches(settings)[0];
  const tournament = tournaments.find(item => item.featured && item.status !== 'COMPLETED' && item.status !== 'CANCELLED') || tournaments.find(item => item.status !== 'COMPLETED' && item.status !== 'CANCELLED');
  const shownOnline = settings.online_count_mode === 'manual' ? settings.online_count_manual || '0' : String(onlineCount);
  const enterCreate = () => { if (!user) return setLocation('/login'); if (!canPlay(user)) return setLocation('/verify?returnTo=/matches'); setCreateOpen(true); };
  const join = async (match: Match) => { if (!user) return setLocation('/login'); if (!canPlay(user)) return setLocation(`/verify?returnTo=/matches/${match.id}`); if (user.balance < match.stake) return setRechargeOpen(true); if (await joinMatch(match.id)) setLocation(`/matches/${match.id}`); };
  return <div className="home-redesigned">
    <section className="home-hero-v2"><div className="shell home-hero-v2-grid"><div className="home-hero-v2-copy"><span className="eyebrow"><span className="pulse-dot" />ساحة المباريات الحية</span><h1>ابدأ مباراة.<br /><em>أثبت مستواك.</em></h1><p>تحديات حقيقية، جوائز واضحة، وضمان يحمي كل مواجهة.</p><div className="home-hero-actions"><button className="primary-button large" onClick={enterCreate}><Swords className="h-5 w-5" />إنشاء مباراة</button><Link href="/matches" className="secondary-button large"><Search className="h-5 w-5" />تصفح التحديات</Link></div><div className="home-live-stats"><span><strong>{players.length}</strong><small>لاعب مسجل</small></span><span><strong>{openMatchCount}</strong><small>مباراة متاحة</small></span><span><strong>{shownOnline}</strong><small>متصل الآن</small></span></div></div><aside className="home-featured-v2"><div className="home-featured-top"><span><span className="live-dot" />مواجهة مميزة</span><span className="home-live-label">مباشرة الآن</span></div>{featured ? <><span className="match-kicker">{featured.title}</span><div className="home-featured-players"><div><UserAvatar username={featured.creatorName} teamId={featured.creatorTeam} large /><strong>{featured.creatorName}</strong><small>{teamById(featured.creatorTeam)?.name || 'فريق مختار'}</small></div><b>VS</b><div><UserAvatar username={featured.opponentName} teamId={featured.opponentTeam} large /><strong>{featured.opponentName}</strong><small>{teamById(featured.opponentTeam)?.name || 'فريق مختار'}</small></div></div><div className="home-featured-prize"><span>الجائزة المضمونة</span><strong>{money(featured.prize)}</strong></div><div className="home-featured-foot"><span><ShieldCheck className="h-4 w-4" />{featured.note}</span><span><Clock3 className="h-4 w-4" />مفتوحة الآن</span></div></> : <div className="home-empty-featured"><Sparkles className="h-8 w-8" /><strong>لا توجد مواجهة مميزة</strong><small>يمكن للإدارة إضافة مواجهة من الإعدادات.</small></div>}</aside></div></section>
    <section className="shell home-section-v2"><div className="home-section-heading-v2"><div><span className="eyebrow muted">تحديات حقيقية</span><h2>المباريات المفتوحة الآن</h2><p>اختر مباراة مناسبة وانضم خلال ثوانٍ.</p></div><Link href="/matches" className="text-link">عرض كل المباريات <ArrowLeft className="h-4 w-4" /></Link></div>{openMatches.length ? <div className="home-match-list">{openMatches.map(match => <article className="home-match-row" key={match.id}><div className="home-match-player"><UserAvatar username={match.creator_name} /><span><strong>{match.creator_name}</strong><small>{match.creator_efootball_id} • {match.platform}</small></span></div><div className="home-match-stake"><small>الرهان</small><strong>{money(match.stake)}</strong></div><div className="home-match-prize"><small>الجائزة</small><strong>{money(match.prize)}</strong></div><button className="primary-button small" onClick={() => join(match)}>انضمام <ArrowLeft className="h-4 w-4" /></button></article>)}</div> : <div className="home-empty-state"><Swords className="h-7 w-7" /><div><strong>لا توجد مباريات مفتوحة حالياً</strong><p>أنشئ أول تحدٍّ وابدأ مواجهة جديدة.</p></div><button className="secondary-button small" onClick={enterCreate}>إنشاء تحدٍّ</button></div>}</section>
    <section className="shell home-section-v2 home-split-grid"><div><div className="home-section-heading-v2 compact"><div><span className="eyebrow muted">نافس بذكاء</span><h2>كيف تبدأ؟</h2></div></div><div className="home-steps"><article><span>01</span><Swords className="h-5 w-5" /><h3>أنشئ تحديك</h3><p>حدد الرهان والمنصة وانتظر منافساً مناسباً.</p></article><article><span>02</span><ShieldCheck className="h-5 w-5" /><h3>العب بأمان</h3><p>يتم حجز الرهان حتى تأكيد النتيجة.</p></article><article><span>03</span><Trophy className="h-5 w-5" /><h3>اربح بعدل</h3><p>تراجع الإدارة النتيجة ثم تصرف الجائزة.</p></article></div></div><aside className="home-tournament-card">{tournament ? <><div className="home-card-kicker"><Trophy className="h-4 w-4" />البطولة القادمة</div><h2>{tournament.title}</h2><p>{tournament.description || tournament.rules}</p><div className="home-tournament-meta"><span><small>الجائزة</small><strong>{money(tournament.prize_pool)}</strong></span><span><small>المشاركون</small><strong>{tournament.participant_count}/{tournament.max_players}</strong></span></div><Link href="/tournaments" className="secondary-button full">استكشف البطولة <ArrowLeft className="h-4 w-4" /></Link></> : <><div className="home-card-kicker"><Trophy className="h-4 w-4" />البطولات</div><h2>قريباً على الساحة</h2><p>ستظهر البطولات القادمة هنا عند فتح التسجيل.</p><Link href="/tournaments" className="secondary-button full">عرض البطولات <ArrowLeft className="h-4 w-4" /></Link></>}</aside></section>
    <section className="shell home-section-v2"><div className="home-section-heading-v2"><div><span className="eyebrow muted">ترتيب حي</span><h2>أفضل اللاعبين</h2><p>النتائج الحقيقية من حسابات المنصة.</p></div><Link href="/leaderboard" className="text-link">لوحة الصدارة <ArrowLeft className="h-4 w-4" /></Link></div><div className="home-leaderboard-preview">{rankedPlayers.map((player, index) => <div className="home-leader-row" key={player.id}><span className={`rank rank-${index + 1}`}>{index + 1}</span><UserAvatar username={player.username} teamId={player.favorite_team} /><span><strong>{player.username}</strong><small>{player.wins} فوز • {player.losses} خسارة</small></span><b>{player.win_rate}%</b></div>)}{!rankedPlayers.length && <div className="home-empty-state"><BarChart3 className="h-7 w-7" /><div><strong>لا توجد بيانات ترتيب بعد</strong><p>ستظهر النتائج بعد أولى المباريات المكتملة.</p></div></div>}</div></section>
    <section className="home-trust-strip"><div className="shell home-trust-grid"><span><ShieldCheck className="h-5 w-5" /><strong>ضمان مالي</strong><small>الرهان محجوز حتى اعتماد النتيجة</small></span><span><Users className="h-5 w-5" /><strong>مجتمع نشط</strong><small>{shownOnline} لاعب متصل الآن</small></span><span><MessageCircle className="h-5 w-5" /><strong>دعم مباشر</strong><small>مساعدة عند الحاجة والنزاعات</small></span></div></section>
    {createOpen && <CreateMatchModal onClose={() => setCreateOpen(false)} />}{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}
  </div>;
}

function LegacyHomePage() {
  const { user, matches, tournaments, settings, onlineCount } = useArena(); const [, setLocation] = useLocation(); const [createOpen, setCreateOpen] = useState(false); const [rechargeOpen, setRechargeOpen] = useState(false); const shownOnline = settings.online_count_mode === 'manual' ? settings.online_count_manual || '0' : String(onlineCount);
  const featuredMatches = readFeaturedMatches(settings); const featured = featuredMatches.find(item => item.active) || featuredMatches[0];
  useEffect(() => { const card = document.querySelector('.hero-card'); if (!card) return; const title = card.querySelector('.featured-match h3'); const players = card.querySelectorAll('.versus span'); const prize = card.querySelector('.featured-prize strong'); const note = card.querySelector('.hero-card-footer span:first-child'); const duration = card.querySelector('.hero-card-footer span:last-child'); const setPlayer = (element: Element, name: string, short: string, opponent = false) => { const badge = element.querySelector('b') || document.createElement('b'); badge.textContent = short; element.textContent = ''; if (!opponent) element.append(badge, document.createTextNode(name)); else element.append(document.createTextNode(name), badge); }; if (!featured) { if (title) title.textContent = 'لا توجد مواجهة الليلة'; if (players[0]) setPlayer(players[0], 'أضف مواجهة من الإعدادات', '—'); if (players[1]) setPlayer(players[1], 'بانتظار الإدارة', '—', true); if (prize) prize.textContent = money(0); if (note) note.textContent = 'حدّدها الإدارة من لوحة التحكم'; if (duration) duration.textContent = '—'; return; } if (title) title.textContent = featured.title; if (players[0]) setPlayer(players[0], featured.creatorName, featured.creatorShort); if (players[1]) setPlayer(players[1], featured.opponentName, featured.opponentShort, true); if (prize) prize.textContent = money(featured.prize); if (note) note.textContent = featured.note; if (duration) duration.textContent = 'مباشرة الآن'; }, [featured]);
   useEffect(() => { const tagline = document.querySelector('.hero-copy > p'); if (tagline) tagline.textContent = 'خض مباريات eFootball وبطولاته مع لاعبين محترفين من كل مكان، مع محفظة آمنة ونظام ضمان يحمي حقوقك في كل مواجهة.'; }, []);
   useEffect(() => { const badges = document.querySelectorAll<HTMLElement>('.hero-card .versus b'); [featured?.creatorTeam, featured?.opponentTeam].forEach((teamId, index) => { const badge = badges[index]; const team = teamById(teamId); if (!badge || !team?.logo) return; const image = document.createElement('img'); image.src = team.logo; image.alt = team.name; badge.replaceChildren(image); badge.classList.add('avatar', 'team-avatar'); }); }, [featured]);
  const enter = (kind: 'match' | 'recharge') => { if (!user) return setLocation('/login'); if (kind === 'match' && !canPlay(user)) return setLocation('/verify?returnTo=/matches'); kind === 'match' ? setCreateOpen(true) : setRechargeOpen(true); };
  return <div className="home-page"><section className="hero-section"><div className="hero-glow" /><div className="shell hero-grid"><div className="hero-copy"><span className="eyebrow"><span className="pulse-dot" />منصة تنافسية موثوقة</span><h1>نافس بقوة.<br /><em>اربح بعدل.</em></h1><p>خض مباريات eFootball وبطولاته مع لاعبين من المغرب، مع محفظة آمنة ونظام ضمان يحمي حقوقك في كل مواجهة.</p><div className="hero-actions"><button className="primary-button large" onClick={() => enter('match')}>إنشاء تحدٍّ جديد <Swords className="h-5 w-5" /></button><button className="secondary-button large" onClick={() => enter('recharge')}>شحن المحفظة <Wallet className="h-5 w-5" /></button></div><div className="hero-stats"><div><strong>1,240+</strong><span>لاعب نشط</span></div><div><strong>{matches.filter(item => item.status === 'OPEN').length + 12}</strong><span>مباراة مفتوحة</span></div><div><strong>{tournaments.length + 8}</strong><span>بطولات ناجحة</span></div></div></div><div className="hero-card"><div className="hero-card-top"><span className="live-dot" />مباريات مباشرة الآن <Sparkles className="h-4 w-4 text-amber-300" /></div><div className="featured-match"><span className="match-kicker">مواجهة الليلة</span><h3>قمة الأبطال</h3><div className="versus"><span><b>YA</b>Yassine_7</span><strong>VS</strong><span>SaraBall<b>SA</b></span></div><div className="featured-prize"><span>الجائزة المضمونة</span><strong>180 د.م.</strong></div></div><div className="hero-card-footer"><span><ShieldCheck className="h-4 w-4 text-emerald-400" /> ضمان مالي مفعّل</span><span>10 دقائق</span></div></div></div></section><section className="shell feature-section"><div className="section-heading"><div><span className="eyebrow muted">ابدأ بخطوة واحدة</span><h2>كل ما تحتاجه للمنافسة</h2></div><Link href="/matches" className="text-link">استكشف المباريات <ArrowLeft className="h-4 w-4" /></Link></div><div className="feature-grid"><Feature icon={Wallet} title="محفظة آمنة" text="اشحن واسحب رصيدك بوضوح، وكل طلب يخضع للمراجعة والتتبع." tone="green" /><Feature icon={Swords} title="مواجهات عادلة" text="أنشئ تحدياً أو انضم إلى مباراة مفتوحة واختر منصتك المفضلة." tone="blue" /><Feature icon={Trophy} title="بطولات حقيقية" text="نافس في بطولات منظمة بجوائز واضحة وقواعد معلنة." tone="amber" /></div></section>{createOpen && <CreateMatchModal onClose={() => setCreateOpen(false)} />}{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function Feature({ icon: Icon, title, text, tone }: { icon: typeof Wallet; title: string; text: string; tone: string }) { return <div className="feature-card"><span className={`panel-icon ${tone}`}><Icon className="h-5 w-5" /></span><h3>{title}</h3><p>{text}</p><ArrowLeft className="feature-arrow h-4 w-4" /></div>; }

function MatchesPage() {
  const { matches, user, joinMatch } = useArena(); const [, setLocation] = useLocation(); const [status, setStatus] = useState('OPEN'); const [platform, setPlatform] = useState('الكل'); const [search, setSearch] = useState(''); const [createOpen, setCreateOpen] = useState(false); const [rechargeOpen, setRechargeOpen] = useState(false);
  const filtered = matches.filter(item => (status === 'ALL' || item.status === status) && (platform === 'الكل' || item.platform === platform) && (!search || `${item.title} ${item.creator_name}`.toLowerCase().includes(search.toLowerCase())));
  const join = async (match: Match) => { if (!user) return setLocation('/login'); if (!canPlay(user)) return setLocation(`/verify?returnTo=/matches/${match.id}`); if (user.balance < match.stake) return setRechargeOpen(true); if (await joinMatch(match.id)) setLocation(`/matches/${match.id}`); };
  return <div className="shell page-wrap"><div className="page-header"><PageTitle icon={Swords} title="المباريات المفتوحة" subtitle="اختر تحدياً مناسباً أو أنشئ مباراة جديدة." /><button className="primary-button" onClick={() => user ? setCreateOpen(true) : setLocation('/login')}><Plus className="h-4 w-4" />إنشاء مباراة</button></div><div className="toolbar"><div className="filter-list">{[['OPEN', 'متاحة'], ['PLAYING', 'جارية'], ['DISPUTE', 'نزاعات'], ['ALL', 'الكل']].map(([id, label]) => <button key={id} onClick={() => setStatus(id)} className={status === id ? 'filter-active' : ''}>{label}</button>)}</div><div className="toolbar-fields"><div className="search-box"><Search className="h-4 w-4" /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث باسم اللاعب أو المباراة" /></div><select value={platform} onChange={event => setPlatform(event.target.value)}><option>الكل</option><option>الهاتف</option><option>PlayStation</option><option>Xbox / PC</option></select></div></div>{filtered.length === 0 ? <div className="match-empty-panel"><Empty icon={Swords} text={status === 'OPEN' ? 'لا توجد مباريات متاحة للانضمام الآن.' : 'لا توجد مباريات مطابقة للبحث حالياً.'} /><div className="match-empty-actions"><p>جرّب تغيير الفلتر، أو أنشئ تحدياً جديداً وحدّد الرهان الذي يناسبك.</p><div className="match-empty-buttons">{status !== 'ALL' && <button className="secondary-button" onClick={() => setStatus('ALL')}>عرض كل المباريات ({matches.length})</button>}<button className="primary-button" onClick={() => user ? setCreateOpen(true) : setLocation('/login')}><Plus className="h-4 w-4" />إنشاء مباراة</button><Link href="/tournaments" className="secondary-button">تصفّح البطولات</Link></div></div></div> : <div className="match-grid">{filtered.map(match => <MatchCard key={match.id} match={match} user={user} onJoin={() => join(match)} onOpen={() => setLocation(`/matches/${match.id}`)} />)}</div>}{createOpen && <CreateMatchModal onClose={() => setCreateOpen(false)} />}{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function MatchCard({ match, user, onJoin, onOpen }: { match: Match; user: User | null; onJoin: () => void; onOpen: () => void }) { const owner = user?.id === match.creator_id; const canRate = Boolean(user && match.status === 'COMPLETED' && match.opponent_id && (user.id === match.creator_id || user.id === match.opponent_id)); return <article className="match-card"><div className="match-card-head"><span><Gamepad2 className="h-4 w-4" />{match.platform}</span><StatusBadge status={match.status === 'OPEN' ? 'OPEN_MATCH' : match.status} /></div><h3>{match.title}</h3><div className="players-line"><div><UserAvatar username={match.creator_name} /><span>{match.creator_name}<small>{match.creator_efootball_id}</small></span></div><strong>VS</strong><div className="opponent"><UserAvatar username={match.opponent_name || 'بانتظار منافس'} /><span>{match.opponent_name || 'بانتظار منافس'}<small>{match.opponent_efootball_id || 'سيظهر بعد الانضمام'}</small></span></div></div><div className="card-metrics"><span>قيمة الرهان<strong>{money(match.stake)}</strong></span><span>الجائزة<strong className="amber-text">{money(match.prize)}</strong></span></div><button className={owner || match.status !== 'OPEN' ? 'secondary-button full' : 'primary-button full'} onClick={owner || match.status !== 'OPEN' ? onOpen : onJoin}>{owner ? 'إدارة المباراة' : match.status === 'OPEN' ? 'قبول التحدي' : 'عرض التفاصيل'}<ArrowLeft className="h-4 w-4" /></button>{owner && match.status === 'OPEN' && <CancelMatchControl match={match} />}{canRate && <Link href={`/rate/${match.id}`} className="text-link">تقييم المنافس</Link>}</article>; }

function MatchDetailPage() {
  const [evidenceFiles, setEvidenceFiles] = useState<File[]>([]);
  const { id } = useParams<{ id: string }>(); const { matches, user, setMatchRoom, addMessage, openDispute, joinMatch } = useArena(); const [, setLocation] = useLocation(); const match = matches.find(item => item.id === id); const [chat, setChat] = useState(''); const [code, setCode] = useState(match?.room_code || ''); const [disputeOpen, setDisputeOpen] = useState(false); const [subject, setSubject] = useState(''); const [details, setDetails] = useState(''); const [message, setMessage] = useState('');
  if (!match) return <div className="shell page-wrap"><Empty text="المباراة غير موجودة." /><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link></div>;
  const participant = !!user && (user.id === match.creator_id || user.id === match.opponent_id); const submitChat = (event: FormEvent) => { event.preventDefault(); addMessage(match.id, chat); setChat(''); }; const submitDispute = (event: FormEvent) => { event.preventDefault(); openDispute(match.id, subject, details, evidenceFiles); setEvidenceFiles([]); setDisputeOpen(false); setMessage('تم فتح النزاع وسيظهر في لوحة الإدارة.'); };
  return <div className="shell page-wrap"><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link>{message && <Notice>{message}</Notice>}<div className="detail-card"><div className="detail-head"><span className="mono">#{match.id} • {match.platform}</span><StatusBadge status={match.status} /></div><div className="detail-versus"><div className="detail-player"><b>{initials(match.creator_name)}</b><strong>{match.creator_name}</strong><small>{match.creator_efootball_id}</small></div><div className="detail-prize"><span>الجائزة</span><strong>{money(match.prize)}</strong><small>الرهان: {money(match.stake)} لكل لاعب</small></div><div className="detail-player"><b>{initials(match.opponent_name || '؟')}</b><strong>{match.opponent_name || 'بانتظار منافس'}</strong><small>{match.opponent_efootball_id || 'لم ينضم بعد'}</small></div></div>{match.status === 'OPEN' && user && user.id !== match.creator_id && <button className="primary-button" onClick={() => void joinMatch(match.id).then(ok => setMessage(ok ? 'تم الانضمام إلى المباراة بنجاح.' : 'تعذر الانضمام إلى المباراة.'))}>قبول التحدي</button>}{participant && <div className="room-code"><span>رمز الغرفة</span><strong>{code || 'لم يحدده المضيف بعد'}</strong><button onClick={() => navigator.clipboard?.writeText(code)} aria-label="نسخ"><Copy className="h-4 w-4" /></button>{user.id === match.creator_id && <div className="inline-edit"><input value={code} onChange={event => setCode(event.target.value)} placeholder="أدخل رمز الغرفة" /><button onClick={() => void setMatchRoom(match.id, code).then(ok => setMessage(ok ? 'تم حفظ رمز الغرفة.' : 'تعذر حفظ رمز الغرفة.'))}><Save className="h-4 w-4" />حفظ</button></div>}</div>}<div className="detail-columns"><div className="chat-panel"><div className="panel-heading"><span><MessageCircle className="h-4 w-4" />محادثة المباراة</span><small>{match.messages.length} رسائل</small></div><div className="chat-messages">{match.messages.length ? match.messages.map(item => <div className={item.user_id === user?.id ? 'chat-message own' : 'chat-message'} key={item.id}><b>{item.username}</b><p>{item.message}</p></div>) : <Empty icon={MessageCircle} text="لا توجد رسائل بعد." />}</div>{participant && <form className="chat-form" onSubmit={submitChat}><input value={chat} onChange={event => setChat(event.target.value)} placeholder="اكتب رسالة للمنافس" /><button aria-label="إرسال"><ArrowLeft className="h-4 w-4" /></button></form>}</div><div className="detail-actions"><h3>إجراءات المباراة</h3><p>احتفظ بإثبات النتيجة والتواصل داخل المنصة لحماية حقوقك.</p>{participant && <button className="danger-button full" onClick={() => setDisputeOpen(true)}><AlertTriangle className="h-4 w-4" />فتح نزاع</button>}</div></div></div>{disputeOpen && <Modal onClose={() => setDisputeOpen(false)}><div className="modal-heading"><span className="panel-icon red"><AlertTriangle className="h-5 w-5" /></span><span><h2>فتح نزاع</h2><p>صف المشكلة بدقة وأرفق التفاصيل اللازمة للإدارة.</p></span></div><form className="modal-body form-stack" onSubmit={submitDispute}><Field label="عنوان النزاع" value={subject} onChange={setSubject} placeholder="مثال: لم يرسل المنافس النتيجة" /><label className="form-field"><span>التفاصيل</span><textarea rows={5} value={details} onChange={event => setDetails(event.target.value)} required /></label><label className="form-field"><span>الأدلة (صور أو فيديو)</span><input type="file" accept="image/*,video/*" multiple onChange={event => setEvidenceFiles(Array.from(event.target.files || []))} /><small>{evidenceFiles.length ? `تم اختيار ${evidenceFiles.length} ملف` : 'يمكنك اختيار أكثر من ملف'}</small></label><button className="danger-button full">إرسال النزاع</button></form></Modal>}</div>;
}

function MatchDetailPageV2() {
  const [evidenceFiles, setEvidenceFiles] = useState<File[]>([]); const { id } = useParams<{ id: string }>(); const { matches, user, setMatchRoom, addMessage, openDispute, joinMatch, submitMatchResultClaim } = useArena(); const [, setLocation] = useLocation(); const match = matches.find(item => item.id === id); const [chat, setChat] = useState(''); const [code, setCode] = useState(match?.room_code || ''); const [disputeOpen, setDisputeOpen] = useState(false); const [subject, setSubject] = useState(''); const [details, setDetails] = useState(''); const [message, setMessage] = useState('');
  if (!match) return <div className="shell page-wrap"><Empty text="المباراة غير موجودة." /><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link></div>;
  const participant = !!user && (user.id === match.creator_id || user.id === match.opponent_id); const canClaim = participant && !!match.opponent_id && !!match.room_code && ['PLAYING', 'COMPLETED', 'DISPUTE'].includes(match.status) && match.payout_status !== 'APPROVED'; const ownClaim = user?.id === match.creator_id ? match.creator_claim : match.opponent_claim; const rivalClaim = user?.id === match.creator_id ? match.opponent_claim : match.creator_claim; const claimText = (winnerId?: string) => winnerId ? winnerId === user?.id ? 'أنا ربحت' : 'الخصم ربح' : 'لم يرسل بعد';
  const submitChat = (event: FormEvent) => { event.preventDefault(); if (!chat.trim()) return; addMessage(match.id, chat); setChat(''); };
  const submitClaim = async (winnerId: string) => { const ok = await submitMatchResultClaim(match.id, winnerId); setMessage(ok ? 'تم إرسال تصريحك بالنتيجة. ستراجع الإدارة تصريحات اللاعبين قبل صرف الجائزة.' : 'تعذر إرسال التصريح. تأكد أن المباراة ما زالت قيد المراجعة.'); };
  const submitDispute = (event: FormEvent) => { event.preventDefault(); openDispute(match.id, subject, details, evidenceFiles); setEvidenceFiles([]); setDisputeOpen(false); setMessage('تم فتح النزاع وسيظهر في لوحة الإدارة.'); };
  return <div className="shell page-wrap"><Link href="/matches" className="back-link"><ArrowRight className="h-4 w-4" />العودة إلى المباريات</Link>{message && <Notice>{message}</Notice>}<div className="detail-card"><div className="detail-head"><span className="mono">#{match.id} • {match.platform}</span><StatusBadge status={match.status} /></div><div className="detail-versus"><div className="detail-player"><b>{initials(match.creator_name)}</b><strong>{match.creator_name}</strong><small>{match.creator_efootball_id}</small></div><div className="detail-prize"><span>الجائزة</span><strong>{money(match.prize)}</strong><small>الرهان: {money(match.stake)} لكل لاعب</small></div><div className="detail-player"><b>{initials(match.opponent_name || '؟')}</b><strong>{match.opponent_name || 'بانتظار منافس'}</strong><small>{match.opponent_efootball_id || 'لم ينضم بعد'}</small></div></div>{match.status === 'OPEN' && user && user.id !== match.creator_id && <button className="primary-button" onClick={() => void joinMatch(match.id).then(ok => setMessage(ok ? 'تم الانضمام إلى المباراة بنجاح.' : 'تعذر الانضمام إلى المباراة.'))}>قبول التحدي</button>}{participant && <div className="room-code"><span>رمز الغرفة</span><strong>{code || 'لم يحدده المضيف بعد'}</strong><button onClick={() => navigator.clipboard?.writeText(code)} aria-label="نسخ"><Copy className="h-4 w-4" /></button>{user && user.id === match.creator_id && <div className="inline-edit"><input value={code} onChange={event => setCode(event.target.value)} placeholder="أدخل رمز الغرفة" /><button onClick={() => void setMatchRoom(match.id, code).then(ok => setMessage(ok ? 'تم حفظ رمز الغرفة.' : 'تعذر حفظ رمز الغرفة.'))}><Save className="h-4 w-4" />حفظ</button></div>}</div>}{canClaim && user && <div className="result-claim-panel"><div className="panel-heading"><span><CheckCircle2 className="h-4 w-4" />تصريح نتيجة المباراة</span><small>اختر بعد انتهاء المواجهة</small></div><p>اختر النتيجة التي تؤكدها. ستظهر تصريحات الطرفين للإدارة قبل اعتماد الجائزة.</p><div className="claim-actions"><button className="primary-button" onClick={() => submitClaim(user.id)}>أنا ربحت</button><button className="secondary-button" onClick={() => submitClaim(user.id === match.creator_id ? match.opponent_id! : match.creator_id)}>الخصم ربح</button></div><div className="claim-summary"><span><small>تصريحك</small><b>{claimText(ownClaim)}</b></span><span><small>تصريح الخصم</small><b>{claimText(rivalClaim)}</b></span></div></div>}<div className="detail-columns"><div className="chat-panel"><div className="panel-heading"><span><MessageCircle className="h-4 w-4" />محادثة المباراة</span><small>{match.messages.length} رسائل</small></div><div className="chat-messages">{match.messages.length ? match.messages.map(item => <div className={item.user_id === user?.id ? 'chat-message own' : 'chat-message'} key={item.id}><b>{item.username}</b><span>{item.message}</span></div>) : <Empty icon={MessageCircle} text="لا توجد رسائل بعد." />}</div>{participant && <form className="chat-form" onSubmit={submitChat}><input value={chat} onChange={event => setChat(event.target.value)} placeholder="اكتب رسالة للمنافس" /><button className="primary-button small" aria-label="إرسال"><ArrowLeft className="h-4 w-4" /></button></form>}</div><aside className="detail-side"><div className="panel-heading"><span><ShieldCheck className="h-4 w-4" />حماية المباراة</span></div><p>لا يتم صرف الجائزة إلا بعد مراجعة النتيجة من الإدارة.</p>{participant && <button className="danger-button full" onClick={() => setDisputeOpen(true)}><AlertTriangle className="h-4 w-4" />فتح نزاع</button>}</aside></div></div>{disputeOpen && <Modal onClose={() => setDisputeOpen(false)} wide><div className="modal-heading"><span className="panel-icon red"><AlertTriangle className="h-5 w-5" /></span><span><h2>فتح نزاع على المباراة</h2><p>أرسل تفاصيل واضحة وأرفق الأدلة إن وجدت.</p></span></div><form className="modal-body form-stack" onSubmit={submitDispute}><Field label="موضوع النزاع" value={subject} onChange={setSubject} placeholder="مثال: النتيجة غير صحيحة" /><label className="form-field"><span>التفاصيل</span><textarea value={details} onChange={event => setDetails(event.target.value)} rows={5} required /></label><label className="form-field"><span>الأدلة</span><input type="file" multiple onChange={event => setEvidenceFiles(Array.from(event.target.files || []))} /></label><button className="primary-button full">إرسال النزاع</button></form></Modal>}</div>;
}

function CancelMatchControl({ match }: { match: Match }) {
  const { cancelMatch } = useArena(); const [busy, setBusy] = useState(false); const [done, setDone] = useState(false);
  const cancel = async () => { if (!window.confirm('هل تريد إلغاء المباراة وإعادة مبلغ الرهان؟')) return; setBusy(true); const ok = await cancelMatch(match.id, 'ألغى المضيف المباراة'); setBusy(false); setDone(ok); };
  if (done) return <Notice type="success">تم إلغاء المباراة وإعادة مبلغ الرهان.</Notice>;
  return <button className="danger-button small" disabled={busy} onClick={() => void cancel()}>{busy ? 'جارٍ الإلغاء...' : 'إلغاء المباراة وإعادة الرهان'}</button>;
}

function TournamentsPage() {
  const { tournaments, user, joinTournament } = useArena(); const [, setLocation] = useLocation(); const [message, setMessage] = useState(''); const [rechargeOpen, setRechargeOpen] = useState(false);
  const join = async (item: Tournament) => { if (!user) return setLocation('/login'); if (user.balance < item.entry_fee) return setRechargeOpen(true); setMessage(await joinTournament(item.id) ? 'تم تسجيلك في البطولة بنجاح.' : 'تعذّر التسجيل في هذه البطولة.'); };
  return <div className="shell page-wrap"><PageTitle icon={Trophy} tone="amber" title="البطولات الرسمية" subtitle="بطولات منظمة بجوائز معلنة وقواعد واضحة." />{message && <Notice>{message}</Notice>}<div className="tournament-grid">{tournaments.map(item => <article className={`tournament-card ${item.featured ? 'is-featured' : ''}`} key={item.id}><div className="tournament-cover">{item.image_url ? <img src={item.image_url} alt={item.title} /> : <Trophy className="h-16 w-16" />}<div className="tournament-cover-overlay" /><span>الجائزة {money(item.prize_pool)}</span><StatusBadge status={item.status || 'UPCOMING'} /></div><div className="tournament-body"><div className="split-row"><h2>{item.title}</h2><span className="capacity">{item.participant_count}/{item.max_players}</span></div><p>{item.description || item.rules}</p><div className="tournament-meta"><span>رسوم التسجيل<strong>{money(item.entry_fee)}</strong></span><span>موعد الانطلاق<strong>{item.start_date || 'سيحدد لاحقاً'}</strong></span><span>المنصة<strong>{item.platform || 'الهاتف'}</strong></span><span>القواعد<strong>{item.rules}</strong></span></div><button className={item.joined ? 'secondary-button full' : 'primary-button full'} disabled={item.joined || item.status === 'CANCELLED' || item.status === 'COMPLETED'} onClick={() => join(item)}>{item.joined ? 'تم التسجيل' : item.status === 'COMPLETED' ? 'انتهت البطولة' : item.status === 'CANCELLED' ? 'البطولة ملغاة' : 'التسجيل في البطولة'}<ArrowLeft className="h-4 w-4" /></button></div></article>)}</div>{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}</div>;
}
function LeaderboardPage() {
  const { players, user, saveProfile } = useArena();
  const rankedPlayers = rankPlayers(players);
  const [showId, setShowId] = useState(Boolean(user?.show_efootball_id));
  const [feedback, setFeedback] = useState('');
  useEffect(() => { setShowId(Boolean(user?.show_efootball_id)); }, [user?.show_efootball_id]);
  const togglePrivacy = async () => {
    if (!user) return;
    const next = !showId;
    const okay = await saveProfile({ whatsapp: user.whatsapp, favorite_team: user.favorite_team || '', favorite_team_logo: user.favorite_team_logo || '', show_efootball_id: next });
    setFeedback(okay ? (next ? 'سيظهر المعرّف كاملاً في لوحة الصدارة.' : 'تم إخفاء المعرّف في لوحة الصدارة.') : 'تعذر تحديث إعداد الخصوصية.');
    if (okay) setShowId(next);
  };
  return <div className="shell page-wrap"><PageTitle icon={BarChart3} tone="amber" title="لوحة الصدارة" subtitle="أفضل اللاعبين حسب عدد الانتصارات ونسبة الفوز." />{user ? <section className="panel-card leaderboard-privacy"><div><strong>خصوصية معرّف eFootball</strong><small>يظهر المعرّف مختصراً للزوار افتراضياً.</small></div><button type="button" className={showId ? 'secondary-button small' : 'primary-button small'} onClick={() => void togglePrivacy()}>{showId ? 'إخفاء المعرّف' : 'إظهار المعرّف'}</button></section> : <Notice>تظهر معرفات eFootball مختصرة للزوار لحماية الخصوصية.</Notice>}<div className="table-card"><table><thead><tr><th>الترتيب</th><th>اللاعب</th><th>المعرّف</th><th>الانتصارات</th><th>الخسائر</th><th>نسبة الفوز</th></tr></thead><tbody>{rankedPlayers.map((player, index) => <tr key={player.id}><td><span className={`rank rank-${index + 1}`}>{index + 1}</span></td><td><span className="table-player"><b>{initials(player.username)}</b>{player.username}</span></td><td className="mono">{publicEfootballId(player)}</td><td className="green-text mono">{player.wins}</td><td className="red-text mono">{player.losses}</td><td className="mono">{player.win_rate}%</td></tr>)}</tbody></table></div>{feedback && <Notice type={feedback.startsWith('تم') || feedback.startsWith('سيظهر') ? 'success' : 'error'}>{feedback}</Notice>}</div>;
}

function LegacyProfilePage() {
  const { user, transactions, withdrawals } = useArena(); const [rechargeOpen, setRechargeOpen] = useState(false); const [withdrawOpen, setWithdrawOpen] = useState(false);
  if (!user) return <div className="shell page-wrap"><Empty icon={UserIcon} text="سجّل الدخول لعرض ملفك الشخصي." /><Link href="/login" className="primary-button">تسجيل الدخول</Link></div>;
  return <div className="shell page-wrap"><div className="profile-grid"><section className="profile-card"><div className="profile-head"><span className="avatar large">{initials(user.username)}</span><span><h1>{user.username}</h1><p>{user.email}</p><StatusBadge status={user.role === 'ADMIN' ? 'APPROVED' : 'OPEN_MATCH'} /></span></div><div className="profile-details"><span><small>معرّف eFootball</small><strong className="mono">{user.efootball_id}</strong></span><span><small>رقم واتساب</small><strong className="mono">{user.whatsapp || 'غير مضاف'}</strong></span><span><small>النتائج</small><strong><i className="green-text">{user.wins} فوز</i> / <i className="red-text">{user.losses} خسارة</i></strong></span></div></section><section className="wallet-card"><div className="split-row"><span className="wallet-label"><Wallet className="h-4 w-4" />المحفظة</span><span className="active-label">نشطة</span></div><small>الرصيد المتاح</small><strong className="wallet-amount">{money(user.balance)}</strong><div className="wallet-actions"><button className="primary-button" onClick={() => setRechargeOpen(true)}><ArrowDownToLine className="h-4 w-4" />شحن</button><button className="secondary-button" onClick={() => setWithdrawOpen(true)}><ArrowUpFromLine className="h-4 w-4" />سحب</button></div></section></div><div className="profile-lower"><section className="panel-card"><div className="panel-heading"><span><Activity className="h-4 w-4" />سجل المعاملات</span><Link href="/profile" className="text-link">عرض الكل</Link></div>{transactions.length ? <div className="transaction-list">{transactions.slice(0, 8).map(item => <div className="transaction-row" key={item.id}><span className={`transaction-icon ${item.amount > 0 ? 'green' : 'blue'}`}>{item.amount > 0 ? <ArrowDownToLine className="h-4 w-4" /> : <ArrowUpFromLine className="h-4 w-4" />}</span><span><strong>{item.description}</strong><small>{date(item.created_at)}</small></span><b className={item.amount > 0 ? 'green-text' : 'red-text'}>{item.amount > 0 ? '+' : ''}{money(item.amount)}</b></div>)}</div> : <Empty icon={Clock3} text="لا توجد معاملات بعد." />}</section><section className="panel-card"><div className="panel-heading"><span><ArrowUpFromLine className="h-4 w-4" />طلبات السحب</span></div>{withdrawals.filter(item => item.userId === user.id).length ? withdrawals.filter(item => item.userId === user.id).slice(0, 6).map(item => <div className="compact-row" key={item.id}><span><strong>#{item.id}</strong><small>{date(item.created_at)}</small></span><span><b>{money(item.amount)}</b><StatusBadge status={item.status} /></span></div>) : <Empty icon={ArrowUpFromLine} text="لم ترسل أي طلب سحب." />}</section></div>{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}{withdrawOpen && <WithdrawModal onClose={() => setWithdrawOpen(false)} />}</div>;
}

function ProfilePage() {
  const { user, transactions, saveProfile } = useArena(); const [rechargeOpen, setRechargeOpen] = useState(false); const [withdrawOpen, setWithdrawOpen] = useState(false); const [whatsapp, setWhatsapp] = useState(''); const [team, setTeam] = useState(''); const [saved, setSaved] = useState(false); const [error, setError] = useState('');
  useEffect(() => { setWhatsapp(user?.whatsapp || ''); setTeam(user?.favorite_team || ''); }, [user?.id, user?.whatsapp, user?.favorite_team]);
  if (!user) return <div className="shell page-wrap"><Empty icon={UserIcon} text="سجّل الدخول لعرض ملفك الشخصي." /><Link href="/login" className="primary-button">تسجيل الدخول</Link></div>;
  const selectedTeam = teamById(team); const verificationText = user.verification_status === 'APPROVED' ? 'حساب موثّق' : user.verification_status === 'PENDING' ? 'التحقق قيد المراجعة' : user.verification_status === 'REJECTED' ? 'يلزم إعادة التحقق' : 'الحساب غير مفعّل للمباريات';
   const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); const okay = await saveProfile({ whatsapp: whatsapp.trim(), favorite_team: team, favorite_team_logo: selectedTeam?.logo || '' }); if (!okay) return setError('تعذر حفظ بيانات الملف الشخصي.'); setSaved(true); setTimeout(() => setSaved(false), 1800); };
  return <div className="shell page-wrap"><div className="profile-grid"><section className="profile-card"><div className="profile-head"><TeamLogo teamId={selectedTeam?.id} large /><span><h1>{user.username}</h1><p>{user.email}</p><StatusBadge status={user.verification_status === 'APPROVED' ? 'APPROVED' : user.verification_status === 'PENDING' ? 'PENDING' : 'OPEN_MATCH'} /></span></div><div className="profile-details"><span><small>الفريق المفضل</small><strong>{selectedTeam?.name || 'لم يختر بعد'}</strong></span><span><small>معرّف eFootball</small><strong className="mono">{user.efootball_id}</strong></span><span><small>النتائج</small><strong><i className="green-text">{user.wins} فوز</i> / <i className="red-text">{user.losses} خسارة</i></strong></span></div></section><section className="wallet-card"><div className="split-row"><span className="wallet-label"><Wallet className="h-4 w-4" />المحفظة</span><span className="active-label">نشطة</span></div><small>الرصيد المتاح</small><strong className="wallet-amount">{money(user.balance)}</strong><div className="wallet-actions"><button className="primary-button" onClick={() => setRechargeOpen(true)}><ArrowDownToLine className="h-4 w-4" />شحن</button><button className="secondary-button" onClick={() => setWithdrawOpen(true)}><ArrowUpFromLine className="h-4 w-4" />سحب</button></div></section></div><form className="panel-card profile-editor" onSubmit={submit}>{saved && <Notice>تم حفظ الملف الشخصي.</Notice>}{error && <Notice type="error">{error}</Notice>}<div className="panel-heading"><span><UserIcon className="h-4 w-4" />تخصيص الملف الشخصي</span><small>يظهر شعار الفريق كصورتك</small></div><div className="form-grid"><Field label="رقم واتساب" value={whatsapp} onChange={setWhatsapp} /><label className="form-field"><span>الفريق المفضل</span><select value={team} onChange={event => setTeam(event.target.value)}><option value="">اختر فريقاً</option>{TEAM_OPTIONS.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label></div><button className="primary-button small"><Save className="h-4 w-4" />حفظ التغييرات</button></form><section className={`panel-card verification-status-card ${user.verification_status === 'APPROVED' ? 'approved' : ''}`}><div className="panel-heading"><span><ShieldCheck className="h-4 w-4" />تفعيل الحساب</span><StatusBadge status={user.verification_status === 'APPROVED' ? 'APPROVED' : user.verification_status === 'PENDING' ? 'PENDING' : user.verification_status === 'REJECTED' ? 'REJECTED' : 'OPEN_MATCH'} /></div><p>{verificationText}. يلزم التفعيل قبل إنشاء أو قبول مباراة.</p>{user.verification_status !== 'APPROVED' && <Link href="/verify?returnTo=/profile" className="primary-button small">فتح صفحة التفعيل <ArrowLeft className="h-4 w-4" /></Link>}</section><section className="panel-card"><div className="panel-heading"><span><Activity className="h-4 w-4" />سجل المعاملات</span></div>{transactions.length ? <div className="transaction-list">{transactions.slice(0, 8).map(item => <div className="transaction-row" key={item.id}><span className={`transaction-icon ${item.amount > 0 ? 'green' : 'blue'}`}>{item.amount > 0 ? <ArrowDownToLine className="h-4 w-4" /> : <ArrowUpFromLine className="h-4 w-4" />}</span><span><strong>{item.description}</strong><small>{date(item.created_at)}</small></span><b className={item.amount > 0 ? 'green-text' : 'red-text'}>{item.amount > 0 ? '+' : ''}{money(item.amount)}</b></div>)}</div> : <Empty text="لا توجد معاملات بعد." />}</section>{rechargeOpen && <RechargeModal onClose={() => setRechargeOpen(false)} />}{withdrawOpen && <WithdrawModal onClose={() => setWithdrawOpen(false)} />}</div>;
}

 function AccountVerificationPage() {
   const { user, settings, verifications, submitVerification } = useArena(); const [, setLocation] = useLocation(); const current = user ? verifications.find(item => item.userId === user.id) : undefined; const [whatsapp, setWhatsapp] = useState(user?.whatsapp || ''); const codeKey = user ? `arenax_verification_code_${user.id}` : ''; const [draftCode] = useState(() => { const stored = codeKey ? sessionStorage.getItem(codeKey) : null; if (stored) return stored; const next = String(Math.floor(100000 + Math.random() * 900000)); if (codeKey) sessionStorage.setItem(codeKey, next); return next; }); const code = current?.status === 'PENDING' ? current.whatsappCode : draftCode; const [file, setFile] = useState<File | null>(null); const [sent, setSent] = useState(false); const [error, setError] = useState('');
  if (!user) return <div className="shell page-wrap"><Empty icon={ShieldCheck} text="سجّل الدخول لتفعيل حسابك." /><Link href="/login" className="primary-button">تسجيل الدخول</Link></div>;
  const returnTo = new URLSearchParams(window.location.search).get('returnTo') || '/matches'; const whatsappLink = (settings.whatsapp_direct_link || DEFAULT_ADMIN_WHATSAPP_LINK).replace(/\/$/, ''); const message = `مرحباً، أريد تفعيل حساب ARENA//X.\nالحساب: ${user.username}\nمعرّف eFootball: ${user.efootball_id}\nرمز التحقق: ${code}`; const openWhatsApp = () => { const separator = whatsappLink.includes('?') ? '&' : '?'; window.open(`${whatsappLink}${separator}text=${encodeURIComponent(message)}`, '_blank', 'noopener,noreferrer'); };
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); if (!whatsapp.trim() || !file) return setError('أدخل رقم واتساب وارفع صورة بطاقة التعريف.'); const okay = await submitVerification(whatsapp, code, file); if (!okay) return setError('تعذر إرسال ملف التحقق. تأكد أن حجم الملف أقل من 8MB.'); setSent(true); };
   if (current?.status === 'PENDING' || sent) return <div className="shell page-wrap"><PageTitle icon={Clock3} title="التحقق قيد المراجعة" subtitle="وصلت بياناتك إلى الإدارة." /><section className="panel-card verification-pending"><CheckCircle2 className="h-12 w-12" /><h2>تم إرسال طلب التفعيل</h2><p>تحقق الإدارة من رقم واتساب وبطاقة التعريف يدوياً. أرسل الرمز إلى الإدارة عبر واتساب إذا لم ترسل الرسالة بعد، ثم انتظر الموافقة.</p><div className="verification-code-readonly">رمز واتساب المحفوظ: <b>{code}</b></div><div className="request-actions"><button className="secondary-button" onClick={openWhatsApp}><MessageCircle className="h-4 w-4" />فتح واتساب بالرمز المحفوظ</button><button className="secondary-button" onClick={() => setLocation(returnTo)}>العودة</button></div></section></div>;
   return <div className="shell page-wrap"><PageTitle icon={ShieldCheck} title="تفعيل الحساب" subtitle="التفعيل مطلوب فقط عند بدء أو قبول مباراة، وليس عند التسجيل." />{current?.status === 'REJECTED' && <Notice type="error">تم رفض الطلب السابق: {current?.adminNote || 'يرجى إرسال بيانات أوضح.'}</Notice>}{error && <Notice type="error">{error}</Notice>}<form className="panel-card verification-form" onSubmit={submit}><div className="verification-step"><span>1</span><div><h3>تأكيد رقم واتساب</h3><p>اكتب الرقم الذي ستتواصل منه، ثم اضغط الزر وافتح واتساب وأرسل الرسالة الجاهزة إلى الإدارة. الرمز يثبت أن رسالة واتساب تخص هذا الحساب.</p><Field label="رقم واتساب" value={whatsapp} onChange={setWhatsapp} placeholder="+212..." /><div className="verification-code-readonly">رمز التحقق الذي سترسله في واتساب: <b>{code}</b></div><button type="button" className="secondary-button small" onClick={openWhatsApp}><MessageCircle className="h-4 w-4" />فتح واتساب وإرسال الرمز</button></div></div><div className="verification-step"><span>2</span><div><h3>إرسال بطاقة التعريف</h3><p>ارفع صورة واضحة للوجه الأمامي. لن تظهر هذه الوثيقة للاعبين الآخرين.</p><label className="upload-drop"><UploadCloud className="h-6 w-6" /><strong>{file?.name || 'اختر صورة بطاقة التعريف'}</strong><small>PNG أو JPG أو PDF، الحد الأقصى 8MB</small><input type="file" accept="image/*,.pdf" onChange={event => setFile(event.target.files?.[0] || null)} /></label></div></div><button className="primary-button full">إرسال طلب التفعيل <ArrowLeft className="h-4 w-4" /></button></form></div>;
}

function AdminPage() {
  const { user } = useArena(); const { section } = useParams<{ section?: string }>();
  if (!user || user.role !== 'ADMIN') return <div className="shell page-wrap"><div className="access-denied"><ShieldAlert className="h-12 w-12" /><h1>الوصول مخصص للإدارة</h1><p>يجب تسجيل الدخول بحساب إداري لعرض هذه الصفحة.</p><Link href="/login" className="primary-button">تسجيل الدخول</Link></div></div>;
  return <AdminLayout section={section || 'overview'} />;
}
const adminLinks = [
  { id: 'overview', label: 'نظرة عامة', icon: LayoutDashboard },
  { id: 'matches', label: 'مراقبة المباريات', icon: Monitor },
  { id: 'tournaments', label: 'إدارة البطولات', icon: Trophy },
  { id: 'store', label: 'المتجر', icon: ShoppingBag },
  { id: 'live', label: 'حالات البث', icon: Video },
  { id: 'store-orders', label: 'طلبات المتجر', icon: Package },
  { id: 'activity', label: 'سجل النشاطات', icon: Activity },
  { id: 'recharges', label: 'طلبات الشحن', icon: ArrowDownToLine },
  { id: 'withdrawals', label: 'طلبات السحب', icon: ArrowUpFromLine },
  { id: 'disputes', label: 'النزاعات', icon: AlertTriangle },
  { id: 'users', label: 'المستخدمون', icon: Users },
  { id: 'verifications', label: 'طلبات التحقق', icon: ShieldCheck },
  { id: 'payment-methods', label: 'طرق الشحن والسحب', icon: Wallet },
  { id: 'earnings', label: 'محفظة المنصة', icon: Wallet },
  { id: 'reports', label: 'التقارير والتصدير', icon: BarChart3 },
  { id: 'support', label: 'الدعم', icon: MessageCircle },
  { id: 'settings', label: 'إعدادات المنصة', icon: Settings },
];
function AdminLayout({ section }: { section: string }) {
  const { matches, tournaments, saveTournament, deleteTournament, recharges, withdrawals, disputes, supportTickets, verifications, storeOrders } = useArena(); const pendingMatchReview = matches.filter(item => item.opponent_id && item.status !== 'OPEN' && item.status !== 'CANCELLED' && item.payout_status !== 'APPROVED').length; const pendingRecharge = recharges.filter(item => item.status === 'PENDING').length; const pendingWithdrawal = withdrawals.filter(item => item.status === 'PENDING').length; const pendingVerification = verifications.filter(item => item.status === 'PENDING').length; const pendingStoreOrder = storeOrders.filter(item => ['NEW', 'UNDER_REVIEW'].includes(item.status)).length; const openDisputes = disputes.filter(item => item.status === 'OPEN' || item.status === 'UNDER_REVIEW').length; const openTickets = supportTickets.filter(item => item.status === 'OPEN' || item.status === 'IN_PROGRESS').length; const current = adminLinks.find(item => item.id === section)?.label || 'نظرة عامة';
          const content = section === 'matches' ? <AdminMatchesPage /> : section === 'tournaments' ? <AdminTournamentsPageV2 tournaments={tournaments} saveTournament={saveTournament} deleteTournament={deleteTournament} /> : section === 'store' ? <StoreAdminPage /> : section === 'live' ? <LiveStateAdminPage /> : section === 'store-orders' ? <StoreOrdersAdminPage /> : section === 'activity' ? <AdminActivityPage /> : section === 'recharges' ? <AdminRechargesPage /> : section === 'withdrawals' ? <AdminWithdrawalsPage /> : section === 'disputes' ? <AdminDisputesPage /> : section === 'users' ? <AdminUsersDetailsPage /> : section === 'verifications' ? <AdminVerificationsPage /> : section === 'payment-methods' ? <AdminPaymentMethodsPage /> : section === 'earnings' ? <AdminEarningsPage /> : section === 'reports' ? <AdminReportsPage /> : section === 'support' ? <AdminSupportPage /> : section === 'settings' ? <><AdminSettingsPage /><FeaturedMatchesSettings /><OnlineCountSettings /></> : <AdminOverview />;
    return <div className="admin-shell shell"><aside className="admin-sidebar"><div className="admin-brand"><span className="brand-mark"><ShieldCheck className="h-5 w-5" /></span><span><strong>مركز الإدارة</strong><small>eFootball ARENA</small></span></div><nav>{adminLinks.map(item => { const Icon = item.icon; const count = item.id === 'matches' ? pendingMatchReview : item.id === 'recharges' ? pendingRecharge : item.id === 'withdrawals' ? pendingWithdrawal : item.id === 'verifications' ? pendingVerification : item.id === 'store-orders' ? pendingStoreOrder : item.id === 'disputes' ? openDisputes : item.id === 'support' ? openTickets : 0; return <Link href={`/admin/${item.id}`} key={item.id} className={section === item.id || (!section && item.id === 'overview') ? 'admin-link active' : 'admin-link'}><Icon className="h-4 w-4" />{item.label}{count > 0 && <span className="nav-count">{count}</span>}</Link>; })}</nav><Link href="/store" className="back-site"><ArrowRight className="h-4 w-4" />العودة إلى المتجر</Link></aside><main className="admin-content"><div className="admin-topbar"><div><span className="admin-kicker">لوحة الإدارة / {current}</span><h1>{current}</h1></div><span className="admin-session"><span className="online-dot" />مسجّل باسم المدير</span></div>{content}</main></div>;
}
function AdminStat({ icon: Icon, label, value, detail, tone = 'green' }: { icon: typeof Wallet; label: string; value: string; detail?: string; tone?: string }) { return <div className="admin-stat"><span className={`stat-icon ${tone}`}><Icon className="h-5 w-5" /></span><span><small>{label}</small><strong>{value}</strong>{detail && <em>{detail}</em>}</span></div>; }
function AdminOverview() {
  const { users, recharges, withdrawals, disputes, activities, matches, tournaments } = useArena(); const pendingRecharge = recharges.filter(item => item.status === 'PENDING').length; const pendingWithdrawal = withdrawals.filter(item => item.status === 'PENDING').length; const openDisputes = disputes.filter(item => item.status === 'OPEN' || item.status === 'UNDER_REVIEW').length;
  return <div className="admin-page"><div className="admin-welcome"><div><span className="eyebrow">مركز العمليات</span><h2>مرحباً بك في لوحة التحكم</h2><p>تابع كل عمليات الشحن والسحب والنزاعات ونشاطات المستخدمين من مكان واحد.</p></div><Link href="/admin/activity" className="secondary-button"><Activity className="h-4 w-4" />عرض السجل الكامل</Link></div><div className="admin-stats"><AdminStat icon={ArrowDownToLine} label="طلبات الشحن المعلقة" value={String(pendingRecharge)} detail="تحتاج إلى مراجعة" /><AdminStat icon={ArrowUpFromLine} label="طلبات السحب المعلقة" value={String(pendingWithdrawal)} detail="تحتاج إلى تنفيذ" tone="amber" /><AdminStat icon={AlertTriangle} label="النزاعات المفتوحة" value={String(openDisputes)} detail="تحتاج إلى قرار" tone="red" /><AdminStat icon={Users} label="إجمالي المستخدمين" value={String(users.length)} detail={`${matches.length} مباريات • ${tournaments.length} بطولات`} tone="blue" /></div><div className="admin-columns"><section className="panel-card"><div className="panel-heading"><span><Activity className="h-4 w-4" />آخر النشاطات</span><Link href="/admin/activity" className="text-link">السجل الكامل</Link></div><ActivityList items={activities.slice(0, 8)} /></section><section className="panel-card quick-panel"><div className="panel-heading"><span><Zap className="h-4 w-4" />إجراءات سريعة</span></div><QuickAction href="/admin/recharges" icon={ArrowDownToLine} title="مراجعة الشحن" detail={`${pendingRecharge} طلبات معلقة`} tone="green" /><QuickAction href="/admin/withdrawals" icon={ArrowUpFromLine} title="معالجة السحب" detail={`${pendingWithdrawal} طلبات معلقة`} tone="amber" /><QuickAction href="/admin/disputes" icon={AlertTriangle} title="فحص النزاعات" detail={`${openDisputes} نزاعات مفتوحة`} tone="red" /><QuickAction href="/admin/users" icon={Users} title="إدارة المستخدمين" detail="الأرصدة والحسابات" tone="blue" /></section></div></div>;
}

function LiveStateAdminPage() {
  const { settings, saveSettings } = useArena();
  const [slots, setSlots] = useState<LiveSlot[]>(() => liveSlotsFrom(settings));
  const [saved, setSaved] = useState(false);
  useEffect(() => { setSlots(liveSlotsFrom(settings)); }, [settings.store_live_slots]);
  const update = (id: string, patch: Partial<LiveSlot>) => setSlots(old => old.map(item => item.id === id ? { ...item, ...patch } : item));
  const save = (event: FormEvent) => { event.preventDefault(); saveSettings({ store_live_slots: JSON.stringify(slots) }); setSaved(true); setTimeout(() => setSaved(false), 1800); };
  const labels: Record<LiveState, string> = { LIVE: 'مباشر الآن', UPCOMING: 'قادم', REPLAY: 'إعادة' };
  return <div className="admin-page"><AdminSectionHeader icon={Video} title="حالات البث" subtitle="اختر الحالة والمصدر. YouTube يبدأ تلقائياً بصوت مكتوم، وOBS يحتاج رابط HLS أو MP4 قابل للتشغيل في المتصفح." />{saved && <Notice>تم حفظ حالات البث.</Notice>}<form className="form-stack" onSubmit={save}><div className="live-admin-grid">{slots.map((slot, index) => <article className="panel-card live-admin-card" key={slot.id}><div className="split-row"><span className="broadcast-channel">CHANNEL 0{index + 1}</span><span className={slot.state === 'LIVE' && slot.url.trim() ? 'active-label' : 'status-info'}>{labels[slot.state]}{slot.state === 'LIVE' && !slot.url.trim() ? ' · أضف الرابط' : ''}</span></div><div className="form-grid"><OptionalField label="عنوان العرض" value={slot.title} onChange={value => update(slot.id, { title: value })} /><label className="form-field"><span>الحالة الفعلية</span><select value={slot.state} onChange={event => { const state = event.target.value as LiveState; update(slot.id, { state, type: state === 'LIVE' ? 'LIVE' : 'VIDEO' }); }}><option value="LIVE">مباشر الآن</option><option value="UPCOMING">قادم</option><option value="REPLAY">إعادة</option></select></label></div><div className="form-grid"><label className="form-field"><span>مصدر البث</span><select value={slot.provider} onChange={event => update(slot.id, { provider: event.target.value as LiveProvider })}><option value="YOUTUBE">YouTube / OBS إلى YouTube</option><option value="DIRECT">OBS مباشر: HLS أو MP4</option></select></label><OptionalField label="الوصف القصير" value={slot.subtitle} onChange={value => update(slot.id, { subtitle: value })} /></div><OptionalField label="رابط YouTube أو HLS / MP4" value={slot.url} onChange={value => update(slot.id, { url: value })} placeholder={slot.provider === 'YOUTUBE' ? 'https://youtube.com/live/...' : 'https://example.com/live/stream.m3u8'} /><OptionalField label="رابط الصورة المصغرة" value={slot.thumbnail} onChange={value => update(slot.id, { thumbnail: value })} placeholder="https://..." /></article>)}</div><button className="primary-button"><Save className="h-4 w-4" />حفظ حالات البث</button></form></div>;
}

function StoreAdminPage() {
  const { settings, saveSettings } = useArena(); const accounts = storeAccountsFrom(settings); const packages = rechargePackagesFrom(settings); const [section, setSection] = useState<'accounts' | 'recharge' | 'live'>('accounts'); const [accountDraft, setAccountDraft] = useState<StoreAccountDraft>(() => accountDraftFrom()); const [editingAccount, setEditingAccount] = useState<string | null>(null); const [accountFile, setAccountFile] = useState<File | null>(null); const [rechargeDraft, setRechargeDraft] = useState<RechargeDraft>(() => rechargeDraftFrom()); const [editingRecharge, setEditingRecharge] = useState<string | null>(null); const [liveDrafts, setLiveDrafts] = useState<LiveSlot[]>(() => liveSlotsFrom(settings)); const [feedback, setFeedback] = useState('');
  const updateAccount = (key: keyof StoreAccountDraft, value: string | boolean) => setAccountDraft(old => ({ ...old, [key]: value }));
  const editAccount = (item: StoreAccount) => { setSection('accounts'); setEditingAccount(item.id); setAccountDraft(accountDraftFrom(item)); setAccountFile(null); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const resetAccount = () => { setEditingAccount(null); setAccountDraft(accountDraftFrom()); setAccountFile(null); };
  const saveAccount = async (event: FormEvent) => { event.preventDefault(); const primaryImage = accountFile ? await fileToDataUrl(accountFile) : accountDraft.primaryImage.trim(); const images = [primaryImage, ...accountDraft.gallery.split(/[\n,]/).map(item => item.trim()).filter(Boolean)].filter(Boolean); const next: StoreAccount = { id: accountDraft.id, title: accountDraft.title.trim(), description: accountDraft.description.trim(), price: Number(accountDraft.price), platform: accountDraft.platform.trim(), tag: accountDraft.tag.trim(), images, available: accountDraft.available }; if (!next.title || !next.description || !next.price || next.price < 0) return setFeedback('أكمل عنوان الحساب ووصفه وسعراً صحيحاً.'); const nextItems = editingAccount ? accounts.map(item => item.id === editingAccount ? next : item) : [next, ...accounts]; saveSettings({ store_accounts: JSON.stringify(nextItems) }); setFeedback(editingAccount ? 'تم تعديل الحساب في المتجر.' : 'تمت إضافة الحساب إلى المتجر.'); resetAccount(); };
  const removeAccount = (item: StoreAccount) => { if (!window.confirm(`حذف العرض «${item.title}»؟`)) return; saveSettings({ store_accounts: JSON.stringify(accounts.filter(entry => entry.id !== item.id)) }); setFeedback('تم حذف الحساب من المتجر.'); if (editingAccount === item.id) resetAccount(); };
  const updateRecharge = (key: keyof RechargeDraft, value: string | boolean) => setRechargeDraft(old => ({ ...old, [key]: value }));
  const editRecharge = (item: RechargePackage) => { setSection('recharge'); setEditingRecharge(item.id); setRechargeDraft(rechargeDraftFrom(item)); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const resetRecharge = () => { setEditingRecharge(null); setRechargeDraft(rechargeDraftFrom()); };
   const saveRecharge = (event: FormEvent) => { event.preventDefault(); const coins = Number(rechargeDraft.amount || rechargeDraft.coins); const next: RechargePackage = { id: rechargeDraft.id, title: rechargeDraft.title.trim(), coins, price: Number(rechargeDraft.price), amount: coins, bonus: rechargeDraft.bonus.trim(), description: rechargeDraft.description.trim(), active: rechargeDraft.active }; if (!next.title || !next.coins || next.coins < 0 || next.price < 0) return setFeedback('أكمل اسم الباقة وعدد الكوينز وسعر الدولار.'); const nextItems = editingRecharge ? packages.map(item => item.id === editingRecharge ? next : item) : [next, ...packages]; saveSettings({ store_recharge_packages: JSON.stringify(nextItems) }); setFeedback(editingRecharge ? 'تم تعديل باقة الكوينز.' : 'تمت إضافة باقة كوينز جديدة.'); resetRecharge(); };
  const removeRecharge = (item: RechargePackage) => { if (!window.confirm(`حذف الباقة «${item.title}»؟`)) return; saveSettings({ store_recharge_packages: JSON.stringify(packages.filter(entry => entry.id !== item.id)) }); setFeedback('تم حذف باقة الشحن.'); if (editingRecharge === item.id) resetRecharge(); };
  useEffect(() => { setLiveDrafts(liveSlotsFrom(settings)); }, [settings.store_live_slots]);
  const updateLive = (id: string, key: keyof LiveSlot, value: string) => setLiveDrafts(old => old.map(item => item.id === id ? { ...item, [key]: value } : item));
  const saveLive = (event: FormEvent) => { event.preventDefault(); saveSettings({ store_live_slots: JSON.stringify(liveDrafts) }); setFeedback('تم حفظ خانات البث الثلاث.'); };
  return <div className="admin-page store-admin-page"><div className="store-admin-intro"><div><span className="eyebrow"><ShoppingBag className="h-3.5 w-3.5" />STORE CONTROL</span><h2>تحكم كامل في متجر ARENA//X</h2><p>أدر الحسابات، باقات الشحن، ومحتوى البث من مكان واحد. التعديلات تظهر مباشرة للمستخدمين.</p></div><div className="store-admin-links"><Link className="secondary-button small" href="/store">معاينة المتجر <ArrowLeft className="h-3.5 w-3.5" /></Link><Link className="secondary-button small" href="/live">معاينة البث <Video className="h-3.5 w-3.5" /></Link></div></div><div className="store-admin-tabs"><button className={section === 'accounts' ? 'active' : ''} onClick={() => setSection('accounts')}><ShoppingBag className="h-4 w-4" />حسابات للبيع <b>{accounts.length}</b></button><button className={section === 'recharge' ? 'active' : ''} onClick={() => setSection('recharge')}><Wallet className="h-4 w-4" />باقات الشحن <b>{packages.length}</b></button><button className={section === 'live' ? 'active' : ''} onClick={() => setSection('live')}><Video className="h-4 w-4" />البث المباشر <b>3</b></button></div>{feedback && <Notice>{feedback}</Notice>}{section === 'accounts' && <div className="store-admin-layout"><form className="panel-card store-admin-editor form-stack" onSubmit={saveAccount}><div className="panel-heading"><span><ImagePlus className="h-4 w-4" />{editingAccount ? 'تعديل حساب' : 'إضافة حساب جديد'}</span>{editingAccount && <button type="button" className="text-link" onClick={resetAccount}>إلغاء التعديل</button>}</div><div className="form-grid"><Field label="عنوان الحساب" value={accountDraft.title} onChange={value => updateAccount('title', value)} placeholder="مثال: ELITE 98" /><Field label="السعر ($)" type="number" value={accountDraft.price} onChange={value => updateAccount('price', value)} /></div><div className="form-grid"><OptionalField label="المنصة" value={accountDraft.platform} onChange={value => updateAccount('platform', value)} placeholder="eFootball Mobile" /><OptionalField label="الشارة" value={accountDraft.tag} onChange={value => updateAccount('tag', value)} placeholder="جديد / مميز" /></div><label className="form-field"><span>وصف الحساب</span><textarea rows={5} value={accountDraft.description} onChange={event => updateAccount('description', event.target.value)} required /></label><div className="form-grid"><OptionalField label="رابط الصورة الرئيسية" value={accountDraft.primaryImage} onChange={value => updateAccount('primaryImage', value)} placeholder="https://..." /><label className="form-field"><span>رفع صورة من الجهاز</span><span className="file-input"><UploadCloud className="h-4 w-4" />{accountFile?.name || 'اختر صورة'}<input type="file" accept="image/*" onChange={event => setAccountFile(event.target.files?.[0] || null)} /></span></label></div><label className="form-field"><span>روابط الصور الإضافية</span><textarea rows={3} value={accountDraft.gallery} onChange={event => updateAccount('gallery', event.target.value)} placeholder="ضع رابطاً في كل سطر" /></label><label className="check-field"><input type="checkbox" checked={accountDraft.available} onChange={event => updateAccount('available', event.target.checked)} />إظهار العرض للمستخدمين</label><div className="request-actions"><button className="primary-button">{editingAccount ? 'حفظ التعديل' : 'إضافة الحساب'} <Save className="h-4 w-4" /></button>{editingAccount && <button type="button" className="secondary-button" onClick={resetAccount}>إلغاء</button>}</div></form><div className="store-admin-list">{accounts.map(item => <article className={`store-admin-card ${!item.available ? 'is-disabled' : ''}`} key={item.id}><StoreImage src={item.images[0]} alt={item.title} /><div className="store-admin-card-copy"><div className="split-row"><span><strong>{item.title}</strong><small>{item.platform} · {money(item.price)}</small></span><span className={item.available ? 'active-label' : 'ban-label'}>{item.available ? 'ظاهر' : 'مخفي'}</span></div><p>{item.description}</p><div className="request-actions"><button className="secondary-button small" onClick={() => editAccount(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button><button className="danger-button small" onClick={() => removeAccount(item)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></div></article>)}</div></div>}{section === 'recharge' && <div className="store-admin-layout"><form className="panel-card store-admin-editor form-stack" onSubmit={saveRecharge}><div className="panel-heading"><span><Package className="h-4 w-4" />{editingRecharge ? 'تعديل باقة شحن' : 'إضافة باقة شحن'}</span>{editingRecharge && <button type="button" className="text-link" onClick={resetRecharge}>إلغاء التعديل</button>}</div><div className="form-grid"><Field label="اسم الباقة" value={rechargeDraft.title} onChange={value => updateRecharge('title', value)} placeholder="شحن 100 DH" /><OptionalField label="النص الدعائي" value={rechargeDraft.bonus} onChange={value => updateRecharge('bonus', value)} placeholder="+5% هدية" /></div><div className="form-grid"><Field label="الرصيد المضاف ($)" type="number" value={rechargeDraft.amount} onChange={value => updateRecharge('amount', value)} /><Field label="السعر ($)" type="number" value={rechargeDraft.price} onChange={value => updateRecharge('price', value)} /></div><label className="form-field"><span>وصف الباقة</span><textarea rows={4} value={rechargeDraft.description} onChange={event => updateRecharge('description', event.target.value)} /></label><label className="check-field"><input type="checkbox" checked={rechargeDraft.active} onChange={event => updateRecharge('active', event.target.checked)} />إظهار الباقة للمستخدمين</label><div className="request-actions"><button className="primary-button">{editingRecharge ? 'حفظ التعديل' : 'إضافة الباقة'} <Save className="h-4 w-4" /></button>{editingRecharge && <button type="button" className="secondary-button" onClick={resetRecharge}>إلغاء</button>}</div></form><div className="recharge-admin-grid">{packages.map(item => <article className={`recharge-admin-card ${!item.active ? 'is-disabled' : ''}`} key={item.id}><span className="recharge-icon"><Wallet className="h-5 w-5" /></span><span className="active-label">{item.active ? 'ظاهرة' : 'مخفية'}</span><h3>{item.title}</h3><strong>{money(item.amount)}</strong>{item.bonus && <small className="green-text">{item.bonus}</small>}<div className="request-actions"><button className="secondary-button small" onClick={() => editRecharge(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button><button className="danger-button small" onClick={() => removeRecharge(item)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></article>)}</div></div>}{section === 'live' && <form className="store-live-admin" onSubmit={saveLive}><div className="panel-card store-live-help"><div><span className="eyebrow"><Radio className="h-3.5 w-3.5" />3 BROADCAST SLOTS</span><h3>محتوى احترافي للبطولات والبث</h3><p>ضع رابط يوتيوب أو رابط فيديو مباشر. لن يبدأ أي فيديو في صفحة المستخدم حتى يضغط عليه.</p></div><button className="primary-button">حفظ خانات البث <Save className="h-4 w-4" /></button></div><div className="live-admin-grid">{liveDrafts.map((slot, index) => <article className="panel-card live-admin-card" key={slot.id}><div className="split-row"><span className="broadcast-channel">CHANNEL 0{index + 1}</span><span className={slot.type === 'LIVE' ? 'active-label' : 'status-info'}>{slot.type === 'LIVE' ? 'مباشر' : 'فيديو'}</span></div><div className="form-grid"><OptionalField label="عنوان العرض" value={slot.title} onChange={value => updateLive(slot.id, 'title', value)} /><label className="form-field"><span>نوع العرض</span><select value={slot.type} onChange={event => updateLive(slot.id, 'type', event.target.value as LiveSlot['type'])}><option value="LIVE">بث مباشر</option><option value="VIDEO">فيديو بطولة</option></select></label></div><OptionalField label="الوصف القصير" value={slot.subtitle} onChange={value => updateLive(slot.id, 'subtitle', value)} /><OptionalField label="رابط يوتيوب / الفيديو" value={slot.url} onChange={value => updateLive(slot.id, 'url', value)} placeholder="https://youtube.com/watch?v=..." /><OptionalField label="رابط الصورة المصغرة" value={slot.thumbnail} onChange={value => updateLive(slot.id, 'thumbnail', value)} placeholder="https://..." /></article>)}</div></form>}</div>;
}

function AdminPaymentMethodsPage() {
  const { paymentMethods, savePaymentMethod, deletePaymentMethod } = useArena(); const [kind, setKind] = useState<PaymentMethod['kind']>('RECHARGE'); const [name, setName] = useState(''); const [details, setDetails] = useState(''); const [editing, setEditing] = useState<string | null>(null); const [error, setError] = useState('');
  const reset = () => { setEditing(null); setName(''); setDetails(''); setKind('RECHARGE'); };
  const edit = (item: PaymentMethod) => { setEditing(item.id); setKind(item.kind); setName(item.name); setDetails(item.details); };
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); const ok = await savePaymentMethod({ id: editing || undefined, kind, name, details, enabled: true, sort_order: paymentMethods.filter(item => item.kind === kind).length * 10 + 10 }); if (!ok) return setError('تعذر حفظ طريقة الدفع.'); reset(); };
  return <div className="admin-page"><AdminSectionHeader icon={Wallet} title="طرق الشحن والسحب" subtitle="أضف أو عدّل أو احذف طرق الدفع التي يراها المستخدمون." /><form className="panel-card form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="form-grid"><label className="form-field"><span>نوع الطريقة</span><select value={kind} onChange={event => setKind(event.target.value as PaymentMethod['kind'])}><option value="RECHARGE">طريقة شحن</option><option value="WITHDRAWAL">طريقة سحب</option></select></label><Field label="اسم الطريقة" value={name} onChange={setName} placeholder="مثال: التحويل البنكي" /></div><label className="form-field"><span>التفاصيل الظاهرة للمستخدم</span><textarea value={details} onChange={event => setDetails(event.target.value)} rows={3} required /></label><div className="request-actions"><button className="primary-button small">{editing ? 'حفظ التعديل' : 'إضافة الطريقة'} <Save className="h-4 w-4" /></button>{editing && <button type="button" className="secondary-button small" onClick={reset}>إلغاء التعديل</button>}</div></form><div className="payment-method-grid">{paymentMethods.length ? paymentMethods.map(item => <article className={`payment-method-card ${item.enabled ? '' : 'is-disabled'}`} key={item.id}><div className="split-row"><span className={`method-kind ${item.kind === 'RECHARGE' ? 'green-text' : 'amber-text'}`}>{item.kind === 'RECHARGE' ? 'شحن' : 'سحب'}</span><span className={item.enabled ? 'active-label' : 'ban-label'}>{item.enabled ? 'مفعلة' : 'متوقفة'}</span></div><h3>{item.name}</h3><p>{item.details}</p><div className="request-actions"><button className="secondary-button small" onClick={() => edit(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button><button className="danger-button small" onClick={() => void deletePaymentMethod(item.id)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></article>) : <Empty icon={Wallet} text="لا توجد طرق دفع بعد." />}</div></div>;
}

function AdminVerificationsPage() {
  const { verifications, approveVerification } = useArena(); const pending = verifications.filter(item => item.status === 'PENDING'); const [notes, setNotes] = useState<Record<string, string>>({}); const [feedback, setFeedback] = useState('');
  const review = async (item: IdentityVerification, approved: boolean) => { const ok = await approveVerification(item.id, approved, notes[item.id] || ''); setFeedback(ok ? approved ? `تم قبول تفعيل ${item.username}.` : `تم رفض تفعيل ${item.username}.` : 'تعذر تحديث طلب التحقق.'); };
  return <div className="admin-page"><AdminSectionHeader icon={ShieldCheck} title="طلبات التحقق" subtitle="راجع رقم واتساب وبطاقة التعريف قبل السماح للمستخدم ببدء المباريات." count={pending.length} tone="blue" />{feedback && <Notice>{feedback}</Notice>}{verifications.length ? <div className="request-list">{verifications.map(item => <article className="request-card verification-admin-card" key={item.id}><div className="request-main"><span className="request-icon blue"><ShieldCheck className="h-5 w-5" /></span><span><strong>{item.username}</strong><small>واتساب: {item.whatsapp} • أرسل في {date(item.submittedAt)}</small></span><StatusBadge status={item.status} /></div><div className="request-details"><span><small>رمز واتساب</small><b className="mono">{item.whatsappCode}</b></span><span><small>الوثيقة</small>{item.documentUrl ? <a className="text-link" href={item.documentUrl} target="_blank" rel="noreferrer">فتح {item.documentName}</a> : <b>{item.documentName}</b>}</span><span><small>ملاحظة الإدارة</small><b>{item.adminNote || 'لا توجد'}</b></span></div>{item.status === 'PENDING' && <><label className="form-field"><span>ملاحظة المراجعة</span><textarea rows={2} value={notes[item.id] || ''} onChange={event => setNotes(old => ({ ...old, [item.id]: event.target.value }))} placeholder="مثال: الصورة واضحة" /></label><div className="request-actions"><button className="primary-button small" onClick={() => void review(item, true)}><Check className="h-4 w-4" />قبول التحقق</button><button className="danger-button small" onClick={() => void review(item, false)}><XCircle className="h-4 w-4" />رفض وإعادة الطلب</button></div></>}</article>)}</div> : <Empty icon={ShieldCheck} text="لا توجد طلبات تحقق بعد." />}</div>;
}

function AdminEarningsPage() {
  const { platformEarnings, matches, recharges, withdrawals } = useArena();
  const [period, setPeriod] = useState('ALL');
  const now = new Date();
  const start = period === 'DAY' ? new Date(now.getFullYear(), now.getMonth(), now.getDate()) : period === 'WEEK' ? new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000) : period === 'MONTH' ? new Date(now.getFullYear(), now.getMonth(), 1) : null;
  const rows = platformEarnings.filter(item => !start || new Date(item.created_at) >= start);
  const total = (items: PlatformEarning[]) => items.reduce((sum, item) => sum + item.commissionAmount, 0);
  const pendingMatches = matches.filter(matchNeedsReview).length;
  const pendingOperations = pendingMatches + recharges.filter(item => item.status === 'PENDING').length + withdrawals.filter(item => item.status === 'PENDING').length;
  const completedOperations = platformEarnings.length + recharges.filter(item => item.status === 'APPROVED').length + withdrawals.filter(item => item.status === 'APPROVED').length;
  const sourceLabel = (source: PlatformEarning['sourceType']) => source === 'MATCH' ? 'مباراة' : source === 'TOURNAMENT' ? 'بطولة' : 'سحب';
  return <div className="admin-page"><AdminSectionHeader icon={Wallet} title="محفظة المنصة" subtitle="سجل كل عمولات المنصة مع تفاصيل المصدر والمبالغ الصافية." /><div className="admin-stats"><AdminStat icon={Wallet} label="إجمالي الأرباح" value={money(total(platformEarnings))} detail="كل العمولات المسجلة" /><AdminStat icon={Activity} label="العمليات" value={String(completedOperations + pendingOperations)} detail="منتهية وجارية" tone="blue" /><AdminStat icon={CheckCircle2} label="عمليات منتهية" value={String(completedOperations)} detail="تم تسجيلها" /><AdminStat icon={Clock3} label="عمليات جارية" value={String(pendingOperations)} detail="تحتاج متابعة" tone="amber" /></div><section className="panel-card earnings-summary"><div className="panel-heading"><span><BarChart3 className="h-4 w-4" />أرباح الفترة</span><small>{rows.length} عملية عمولة</small></div><div className="filter-list"><button className={period === 'ALL' ? 'filter-active' : ''} onClick={() => setPeriod('ALL')}>الأرباح كاملة</button><button className={period === 'DAY' ? 'filter-active' : ''} onClick={() => setPeriod('DAY')}>اليوم</button><button className={period === 'WEEK' ? 'filter-active' : ''} onClick={() => setPeriod('WEEK')}>الأسبوع</button><button className={period === 'MONTH' ? 'filter-active' : ''} onClick={() => setPeriod('MONTH')}>الشهر</button></div><strong className="earnings-total">{money(total(rows))}</strong></section>{rows.length ? <div className="request-list">{rows.map(item => <article className="request-card" key={item.id}><div className="request-main"><span className="request-icon green"><Wallet className="h-5 w-5" /></span><span><strong>{item.description}</strong><small>{sourceLabel(item.sourceType)} • #{item.sourceId} • {date(item.created_at)}</small></span><span className="request-amount green-text">+{money(item.commissionAmount)}</span></div><div className="request-details"><span><small>المبلغ الإجمالي</small><b>{money(item.grossAmount)}</b></span><span><small>عمولة المنصة</small><b>{(item.commissionRate * 100).toFixed(1)}%</b></span><span><small>الصافي للاعب</small><b>{money(item.netAmount)}</b></span><span><small>معرّف المصدر</small><b className="mono">{item.matchId || item.tournamentId || item.withdrawalId || item.sourceId}</b></span></div></article>)}</div> : <Empty icon={Wallet} text="لا توجد أرباح مسجلة في هذه الفترة." />}</div>;
}

function QuickAction({ href, icon: Icon, title, detail, tone }: { href: string; icon: typeof Wallet; title: string; detail: string; tone: string }) { return <Link href={href} className="quick-action"><span className={`stat-icon ${tone}`}><Icon className="h-4 w-4" /></span><span><strong>{title}</strong><small>{detail}</small></span><ArrowLeft className="h-4 w-4" /></Link>; }
function ActivityList({ items }: { items: ActivityRecord[] }) { return items.length ? <div className="activity-list">{items.map(item => <div className="activity-row" key={item.id}><span className={`activity-icon ${item.category.toLowerCase()}`}><Activity className="h-4 w-4" /></span><span><strong>{item.action}</strong><small>{item.description} • {item.username} • {date(item.created_at)}</small></span>{item.amount !== undefined && <b className="mono">{money(item.amount)}</b>}</div>)}</div> : <Empty text="لا توجد نشاطات مسجلة بعد." />; }

function AdminRechargesPage() {
  const { recharges, approveRecharge } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState(''); const rows = recharges.filter(item => (filter === 'ALL' || item.status === filter) && (!query || `${item.id} ${item.username} ${item.whatsapp}`.toLowerCase().includes(query.toLowerCase())));
  return <div className="admin-page"><AdminSectionHeader icon={ArrowDownToLine} title="طلبات الشحن" subtitle="راجع التحويلات وأضف الرصيد بعد التأكد من البيانات." count={recharges.filter(item => item.status === 'PENDING').length} /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'APPROVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <article className="request-card" key={item.id}><div className="request-main"><span className="request-icon green"><ArrowDownToLine className="h-5 w-5" /></span><span><strong>{item.username}</strong><small>#{item.id} • {date(item.created_at)}</small></span><span className="request-amount green-text">+{money(item.amount)}</span><StatusBadge status={item.status} /></div><div className="request-details"><span><small>طريقة الدفع</small><b>{item.payment_method}</b></span><span><small>واتساب</small><b className="mono">{item.whatsapp || 'غير متوفر'}</b></span><span><small>ملاحظات</small><b>{item.notes || 'لا توجد ملاحظات'}</b></span></div>{item.status === 'PENDING' && <div className="request-actions"><button className="primary-button small" onClick={() => approveRecharge(item.id, true)}><Check className="h-4 w-4" />اعتماد وإضافة الرصيد</button><button className="danger-button small" onClick={() => approveRecharge(item.id, false)}><XCircle className="h-4 w-4" />رفض الطلب</button></div>}</article>)}</div> : <Empty icon={ArrowDownToLine} text="لا توجد طلبات شحن بهذه الحالة." />}</div>;
}
function AdminWithdrawalsPage() {
  const { withdrawals, approveWithdrawal } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState(''); const rows = withdrawals.filter(item => (filter === 'ALL' || item.status === filter) && (!query || `${item.id} ${item.username} ${item.destination}`.toLowerCase().includes(query.toLowerCase())));
  return <div className="admin-page"><AdminSectionHeader icon={ArrowUpFromLine} title="طلبات السحب" subtitle="نفّذ طلبات السحب أو ارفضها مع إعادة المبلغ تلقائياً عند الرفض." count={withdrawals.filter(item => item.status === 'PENDING').length} tone="amber" /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'APPROVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <article className="request-card" key={item.id}><div className="request-main"><span className="request-icon amber"><ArrowUpFromLine className="h-5 w-5" /></span><span><strong>{item.username}</strong><small>#{item.id} • {date(item.created_at)}</small></span><span className="request-amount amber-text">-{money(item.amount)}</span><StatusBadge status={item.status} /></div><div className="request-details"><span><small>المبلغ المطلوب</small><b>{money(item.amount)}</b></span><span><small>عمولة المنصة (5%)</small><b>{money(item.fee || item.amount * 0.05)}</b></span><span><small>الصافي المحوّل</small><b>{money(item.payoutAmount || item.amount * 0.95)}</b></span><span><small>طريقة الاستلام</small><b>{item.method}</b></span><span><small>الحساب أو الهاتف</small><b className="mono">{item.destination}</b></span><span><small>ملاحظات</small><b>{item.notes || 'لا توجد ملاحظات'}</b></span></div>{item.status === 'PENDING' && <div className="request-actions"><button className="primary-button small" onClick={() => approveWithdrawal(item.id, true)}><Check className="h-4 w-4" />تأكيد التحويل</button><button className="danger-button small" onClick={() => approveWithdrawal(item.id, false)}><XCircle className="h-4 w-4" />رفض وإعادة الرصيد</button></div>}</article>)}</div> : <Empty icon={ArrowUpFromLine} text="لا توجد طلبات سحب بهذه الحالة." />}</div>;
}
function matchNeedsReview(match: Match) { return Boolean(match.opponent_id && !['OPEN', 'CANCELLED'].includes(match.status) && match.payout_status !== 'APPROVED'); }
function AdminMatchesPage() {
  const { matches } = useArena(); const [filter, setFilter] = useState('PENDING'); const [query, setQuery] = useState('');
  const rows = matches.filter(item => { const matchesFilter = filter === 'ALL' || (filter === 'PENDING' ? matchNeedsReview(item) : item.status === filter); const matchesQuery = !query || `${item.id} ${item.title} ${item.creator_name} ${item.opponent_name || ''} ${item.winner_name || ''}`.toLowerCase().includes(query.toLowerCase()); return matchesFilter && matchesQuery; });
  return <div className="admin-page"><AdminSectionHeader icon={Monitor} title="مراقبة المباريات" subtitle="راجع المواجهات، حدّد الفائز، ثم اعتمد صرف الجائزة أو علّقها عند وجود شك." count={matches.filter(matchNeedsReview).length} tone="blue" /><AdminFilters filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} options={['PENDING', 'PLAYING', 'DISPUTE', 'COMPLETED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <MatchReviewCardWithClaims match={item} key={item.id} />)}</div> : <Empty icon={Monitor} text="لا توجد مباريات تحتاج إلى مراجعة بهذه الحالة." />}</div>;
}
function MatchReviewCard({ match }: { match: Match }) {
  const { setMatchResult, reviewMatchPayout } = useArena(); const [winnerId, setWinnerId] = useState(match.winner_id || ''); const [note, setNote] = useState(match.payout_note || ''); const [feedback, setFeedback] = useState(''); const [busy, setBusy] = useState(false); const players = [{ id: match.creator_id, name: match.creator_name, efootballId: match.creator_efootball_id }, ...(match.opponent_id ? [{ id: match.opponent_id, name: match.opponent_name || 'اللاعب المنافس', efootballId: match.opponent_efootball_id || 'غير متوفر' }] : [])];
  const submitResult = async () => { if (!winnerId) return setFeedback('اختر الفائز قبل تسجيل النتيجة.'); setBusy(true); const ok = await setMatchResult(match.id, winnerId, note); setBusy(false); setFeedback(ok ? 'تم تسجيل النتيجة. الجائزة الآن بانتظار اعتماد الإدارة.' : 'تعذر تسجيل النتيجة. حاول مرة أخرى.'); };
  const approve = async () => { if (!match.winner_id) return setFeedback('سجّل النتيجة أولاً ثم اعتمد الجائزة.'); if (winnerId !== match.winner_id) return setFeedback('احفظ اختيار الفائز أولاً قبل اعتماد الجائزة.'); setBusy(true); const ok = await reviewMatchPayout(match.id, true, note); setBusy(false); setFeedback(ok ? 'تم اعتماد الجائزة وتسجيل العملية.' : 'تعذر اعتماد الجائزة.'); };
  const reject = async () => { if (!match.winner_id) return setFeedback('سجّل النتيجة أولاً.'); if (!note.trim()) return setFeedback('اكتب سبب تعليق أو رفض صرف الجائزة.'); setBusy(true); const ok = await reviewMatchPayout(match.id, false, note); setBusy(false); setFeedback(ok ? 'تم تعليق صرف الجائزة وفتح المباراة للمراجعة.' : 'تعذر تحديث قرار الجائزة.'); };
  return <article className="request-card match-review-card"><div className="request-main"><span className="request-icon blue"><Monitor className="h-5 w-5" /></span><span><strong>{match.title}</strong><small>#{match.id} • {match.creator_name} ضد {match.opponent_name || 'بانتظار منافس'} • {date(match.created_at || new Date().toISOString())}</small></span><StatusBadge status={match.status} />{match.payout_status && <StatusBadge status={match.payout_status} />}</div><div className="request-details"><span><small>المنصة</small><b>{match.platform}</b></span><span><small>الرهان</small><b>{money(match.stake)}</b></span><span><small>الجائزة</small><b className="amber-text">{money(match.prize)}</b></span><span><small>الفائز المسجل</small><b>{match.winner_name || 'لم يحدد بعد'}</b></span></div>{match.opponent_id ? <div className="match-review-controls"><div className="form-grid"><label className="form-field"><span>تحديد الفائز</span><select value={winnerId} onChange={event => setWinnerId(event.target.value)}><option value="">اختر اللاعب الفائز</option>{players.map(player => <option value={player.id} key={player.id}>{player.name} • {player.efootballId}</option>)}</select></label><label className="form-field"><span>ملاحظة الإدارة</span><input value={note} onChange={event => setNote(event.target.value)} placeholder="سبب القرار أو ملاحظاته" /></label></div>{feedback && <Notice type={feedback.startsWith('تم') ? 'success' : 'error'}>{feedback}</Notice>}<div className="request-actions"><button className="secondary-button small" disabled={busy} onClick={submitResult}><Save className="h-4 w-4" />{match.winner_id ? 'تحديث النتيجة' : 'تسجيل النتيجة'}</button>{match.winner_id && match.payout_status !== 'APPROVED' && <><button className="primary-button small" disabled={busy} onClick={approve}><Check className="h-4 w-4" />اعتماد دفع الجائزة</button><button className="danger-button small" disabled={busy} onClick={reject}><XCircle className="h-4 w-4" />رفض الدفع وفتح نزاع</button></>}</div></div> : <div className="quote-box">هذه المباراة بانتظار انضمام منافس قبل تسجيل النتيجة.</div>}{match.payout_status === 'APPROVED' && <div className="resolution-box"><CheckCircle2 className="h-4 w-4" />تم اعتماد صرف {money(match.prize)} للفائز {match.winner_name}.</div>}{match.payout_status === 'REJECTED' && <div className="quote-box">تم تعليق صرف الجائزة: {match.payout_note || 'بانتظار قرار جديد من الإدارة.'}</div>}</article>;
}
function MatchRoomControl({ match }: { match: Match }) {
  const { setMatchRoom } = useArena(); const [roomCode, setRoomCode] = useState(match.room_code || ''); const [feedback, setFeedback] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { setRoomCode(match.room_code || ''); }, [match.room_code]);
  if (match.status !== 'PLAYING' || !match.opponent_id) return null;
  const save = async () => { setFeedback(''); setBusy(true); const ok = await setMatchRoom(match.id, roomCode); setBusy(false); setFeedback(ok ? 'تم نشر أيدي الغرفة للاعبين.' : 'تعذر نشر أيدي الغرفة.'); };
  return <div className="admin-room-control"><div><strong>{match.room_code ? 'غرفة المباراة منشورة' : 'جاري إنشاء الغرفة'}</strong><small>{match.room_code ? 'ينسخ اللاعبان الأيدي، ثم يبدأ عداد المباراة.' : 'أنشئ الغرفة بإعدادات عادلة ثم أدخل أيديها هنا.'}</small></div><div className="room-control-form"><input value={roomCode} onChange={event => setRoomCode(event.target.value)} placeholder="أيدي الغرفة" /><button className="primary-button small" disabled={busy || !roomCode.trim()} onClick={() => void save()}>{busy ? 'جارٍ الحفظ...' : match.room_code ? 'تحديث الأيدي' : 'نشر أيدي الغرفة'} <Save className="h-4 w-4" /></button></div>{feedback && <small className={feedback.startsWith('تم') ? 'green-text' : 'red-text'}>{feedback}</small>}</div>;
}
function MatchReviewCardWithClaims({ match }: { match: Match }) { const claimText = (claim: string | undefined, playerId: string, playerName: string) => claim ? `${claim === playerId ? 'أنا ربحت' : 'الخصم ربح'} • ${playerName}` : 'لم يرسل بعد'; return <div className="match-review-wrapper"><div className="admin-claim-summary"><span><small>تصريح {match.creator_name}</small><b>{claimText(match.creator_claim, match.creator_id, match.creator_name)}</b></span><span><small>تصريح {match.opponent_name || 'الخصم'}</small><b>{match.opponent_id ? claimText(match.opponent_claim, match.opponent_id, match.opponent_name || 'الخصم') : 'بانتظار منافس'}</b></span></div><MatchRoomControl match={match} /><MatchReviewCard match={match} /></div>; }
function AdminTournamentsPage() {
  const { tournaments, saveTournament, deleteTournament } = useArena(); const [query, setQuery] = useState(''); const [editorOpen, setEditorOpen] = useState(false); const [editing, setEditing] = useState<Tournament | undefined>();
  const rows = tournaments.filter(item => !query || `${item.title} ${item.platform || ''} ${item.rules}`.toLowerCase().includes(query.toLowerCase()));
  const openEditor = (item?: Tournament) => { setEditing(item); setEditorOpen(true); };
  const remove = async (item: Tournament) => { if (window.confirm(`حذف البطولة «${item.title}»؟`)) await deleteTournament(item.id); };
  return <div className="admin-page"><div className="admin-tournaments-hero"><AdminSectionHeader icon={Trophy} title="إدارة البطولات" subtitle="أنشئ بطولات عصرية وعدّل كل تفاصيلها، بما فيها صورة الغلاف والحالة." tone="amber" /><button className="primary-button" onClick={() => openEditor()}><Plus className="h-4 w-4" />إضافة بطولة</button></div><div className="admin-filters"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث في البطولات" /></div><span className="records-count">{rows.length} بطولة</span></div>{rows.length ? <div className="admin-tournament-grid">{rows.map(item => <article className="admin-tournament-card" key={item.id}><div className="admin-tournament-media">{item.image_url ? <img src={item.image_url} alt={item.title} /> : <ImageIcon className="h-10 w-10" />}<div><StatusBadge status={item.status || 'UPCOMING'} />{item.featured && <span className="featured-label">مميزة</span>}</div></div><div className="admin-tournament-body"><div className="split-row"><div><h3>{item.title}</h3><p>{item.description || item.rules}</p></div><span className="capacity">{item.participant_count}/{item.max_players}</span></div><div className="admin-tournament-facts"><span><small>الجائزة</small><b className="amber-text">{money(item.prize_pool)}</b></span><span><small>الدخول</small><b>{money(item.entry_fee)}</b></span><span><small>المنصة</small><b>{item.platform || 'الهاتف'}</b></span><span><small>البداية</small><b>{item.start_date || 'لاحقاً'}</b></span></div><div className="admin-tournament-actions"><button className="secondary-button small" onClick={() => openEditor(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button><button className="danger-button small" onClick={() => void remove(item)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></div></article>)}</div> : <Empty icon={Trophy} text="لا توجد بطولات مطابقة للبحث." />}{editorOpen && <TournamentEditorModal tournament={editing} onClose={() => setEditorOpen(false)} />}</div>;
}
function TournamentEditorModal({ tournament, onClose }: { tournament?: Tournament; onClose: () => void }) {
  const { saveTournament } = useArena(); const [draft, setDraft] = useState<TournamentDraft>(() => toTournamentDraft(tournament)); const [imageFile, setImageFile] = useState<File>(); const [error, setError] = useState(''); const update = (key: keyof TournamentDraft, value: string | number | boolean) => setDraft(old => ({ ...old, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!draft.title.trim()) return setError('اكتب اسم البطولة.'); if (draft.max_players < 2) return setError('عدد اللاعبين يجب أن يكون 2 على الأقل.'); if (draft.prize_pool < 0 || draft.entry_fee < 0) return setError('القيم المالية لا يمكن أن تكون سالبة.'); const okay = await saveTournament({ ...draft, title: draft.title.trim(), rules: draft.rules.trim(), description: draft.description.trim() }, imageFile); if (!okay) return setError('تعذر حفظ البطولة. تحقق من إعداد Storage في Supabase ثم حاول مرة أخرى.'); onClose(); };
  return <Modal onClose={onClose} wide><div className="modal-heading"><span className="panel-icon amber"><Trophy className="h-5 w-5" /></span><span><h2>{tournament ? 'تعديل البطولة' : 'إضافة بطولة جديدة'}</h2><p>تحكم كامل في بيانات البطولة، الحالة، وصورة الغلاف.</p></span></div><form className="modal-body form-stack" onSubmit={submit}>{error && <Notice type="error">{error}</Notice>}<div className="form-grid"><Field label="اسم البطولة" value={draft.title} onChange={value => update('title', value)} /><Field label="المنصة" value={draft.platform} onChange={value => update('platform', value)} /></div><div className="form-grid"><Field label="قيمة الجوائز ($)" type="number" value={String(draft.prize_pool)} onChange={value => update('prize_pool', Number(value))} /><Field label="رسوم التسجيل ($)" type="number" value={String(draft.entry_fee)} onChange={value => update('entry_fee', Number(value))} /><Field label="الحد الأقصى للاعبين" type="number" value={String(draft.max_players)} onChange={value => update('max_players', Number(value))} /></div><div className="form-grid"><Field label="موعد البداية" value={draft.start_date} onChange={value => update('start_date', value)} placeholder="مثال: الجمعة، 21:00" /><Field label="موعد النهاية" value={draft.end_date} onChange={value => update('end_date', value)} placeholder="اختياري" /></div><div className="form-grid"><label className="form-field"><span>حالة البطولة</span><select value={draft.status} onChange={event => update('status', event.target.value as TournamentStatus)}><option value="UPCOMING">قادمة</option><option value="LIVE">مباشرة</option><option value="COMPLETED">مكتملة</option><option value="CANCELLED">ملغاة</option></select></label><label className="form-field"><span>صورة الغلاف من الجهاز</span><span className="file-input"><UploadCloud className="h-4 w-4" />{imageFile ? imageFile.name : 'اختر صورة'}<input type="file" accept="image/*" onChange={event => setImageFile(event.target.files?.[0])} /></span></label></div><label className="form-field"><span>رابط صورة الغلاف (اختياري)</span><input value={draft.image_url} onChange={event => update('image_url', event.target.value)} placeholder="https://..." /></label><label className="form-field"><span>وصف قصير</span><textarea rows={2} value={draft.description} onChange={event => update('description', event.target.value)} placeholder="وصف يظهر للاعبين" /></label><label className="form-field"><span>القواعد</span><textarea rows={3} value={draft.rules} onChange={event => update('rules', event.target.value)} /></label><label className="check-field"><input type="checkbox" checked={draft.featured} onChange={event => update('featured', event.target.checked)} /><span>إظهار كبطولة مميزة</span></label><button className="primary-button full"><Save className="h-4 w-4" />حفظ بيانات البطولة</button></form></Modal>;
}
function AdminSectionHeader({ icon: Icon, title, subtitle, count, tone = 'green' }: { icon: typeof Wallet; title: string; subtitle: string; count?: number; tone?: string }) { return <div className="section-admin-header"><div className="page-title"><span className={`page-icon tone-${tone}`}><Icon className="h-6 w-6" /></span><span><h2>{title}</h2><p>{subtitle}</p></span></div>{count !== undefined && <span className="header-count">{count} قيد المراجعة</span>}</div>; }
function AdminFilters({ filter, setFilter, query, setQuery, options }: { filter: string; setFilter: (value: string) => void; query: string; setQuery: (value: string) => void; options: string[] }) { return <div className="admin-filters"><div className="filter-list">{options.map(option => <button key={option} className={filter === option ? 'filter-active' : ''} onClick={() => setFilter(option)}>{statusLabel[option] || 'الكل'}</button>)}</div><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="بحث في الطلبات" /></div></div>; }

function AdminDisputesPage() {
  const { disputes } = useArena(); const [filter, setFilter] = useState('ALL'); const rows = disputes.filter(item => filter === 'ALL' || item.status === filter); return <div className="admin-page"><AdminSectionHeader icon={AlertTriangle} title="إدارة النزاعات" subtitle="راجع أدلة اللاعبين واتخذ قراراً واضحاً مع توثيق السبب." tone="red" /><AdminFilters filter={filter} setFilter={setFilter} query="" setQuery={() => undefined} options={['OPEN', 'UNDER_REVIEW', 'RESOLVED', 'REJECTED', 'ALL']} />{rows.length ? <div className="request-list">{rows.map(item => <DisputeRow item={item} key={item.id} />)}</div> : <Empty icon={AlertTriangle} text="لا توجد نزاعات في هذا القسم." />}</div>;
}
 function DisputeRow({ item }: { item: Dispute }) { const { resolveDispute } = useArena(); const [resolution, setResolution] = useState(item.resolution || ''); const [status, setStatus] = useState<Dispute['status']>(item.status); const [open, setOpen] = useState(item.status === 'OPEN'); return <article className="request-card dispute-card"><div className="request-main"><span className="request-icon red"><AlertTriangle className="h-5 w-5" /></span><span><strong>{item.subject}</strong><small>{item.username} • المباراة #{item.matchId} • {date(item.created_at)}</small></span><StatusBadge status={item.status} /><button className="icon-button" onClick={() => setOpen(!open)} aria-label="عرض التفاصيل"><ChevronDown className={`h-4 w-4 ${open ? 'rotate-180' : ''}`} /></button></div>{open && <div className="dispute-details"><div className="quote-box">{item.details}</div>{item.evidence?.length ? <div className="request-details"><span><small>الأدلة</small><span>{item.evidence.map((evidence, index) => evidence.startsWith('http') ? <a className="text-link" href={evidence} target="_blank" rel="noreferrer" key={evidence}>عرض الدليل {index + 1}</a> : <b key={evidence}>{evidence}</b>)}</span></span></div> : null}{item.resolution && <div className="resolution-box"><CheckCircle2 className="h-4 w-4" />{item.resolution}</div>}{!['RESOLVED', 'REJECTED'].includes(item.status) && <><label className="form-field"><span>قرار الإدارة</span><select value={status} onChange={event => setStatus(event.target.value as Dispute['status'])}><option value="UNDER_REVIEW">قيد التحقيق</option><option value="RESOLVED">تم الحل</option><option value="REJECTED">مرفوض</option></select></label><label className="form-field"><span>ملاحظات القرار</span><textarea rows={3} value={resolution} onChange={event => setResolution(event.target.value)} placeholder="اكتب سبب القرار بوضوح" /></label><button className="primary-button small" onClick={() => resolveDispute(item.id, status, resolution)}><Save className="h-4 w-4" />حفظ القرار</button></>}</div>}</article>; }

function AdminActivityPage() {
  const { activities } = useArena(); const [query, setQuery] = useState(''); const [category, setCategory] = useState('ALL'); const rows = activities.filter(item => (category === 'ALL' || item.category === category) && (!query || `${item.action} ${item.description} ${item.username}`.toLowerCase().includes(query.toLowerCase()))); return <div className="admin-page"><AdminSectionHeader icon={Activity} title="سجل النشاطات" subtitle="سجل موحّد لكل ما يحدث داخل المنصة، مع اسم المستخدم والوقت والتفاصيل." /><div className="admin-filters"><div className="filter-list">{['ALL', 'RECHARGE', 'WITHDRAWAL', 'MATCH', 'DISPUTE', 'ACCOUNT'].map(item => <button key={item} className={category === item ? 'filter-active' : ''} onClick={() => setCategory(item)}>{item === 'ALL' ? 'الكل' : categoryLabel(item)}</button>)}</div><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث في السجل" /></div></div><div className="panel-card"><ActivityList items={rows} /></div></div>; }
function categoryLabel(category: string) { return ({ RECHARGE: 'الشحن', WITHDRAWAL: 'السحب', MATCH: 'المباريات', DISPUTE: 'النزاعات', ACCOUNT: 'الحسابات', TOURNAMENT: 'البطولات', ADMIN: 'الإدارة' } as Record<string, string>)[category] || category; }

function AdminUsersPage() {
  const { users, adjustUser } = useArena(); const [query, setQuery] = useState(''); const [amounts, setAmounts] = useState<Record<string, string>>({}); const rows = users.filter(item => !query || `${item.username} ${item.email} ${item.efootball_id}`.toLowerCase().includes(query.toLowerCase())); return <div className="admin-page"><AdminSectionHeader icon={Users} title="إدارة المستخدمين" subtitle="راجع الحسابات وعدّل الأرصدة مع تسجيل كل عملية في السجل." /><div className="admin-filters"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث باسم اللاعب أو بريده" /></div></div>{rows.length ? <div className="user-list">{rows.map(item => <div className="user-admin-row" key={item.id}><span className="avatar">{initials(item.username)}</span><span className="user-admin-main"><strong>{item.username}</strong><small>{item.email} • {item.efootball_id}</small></span><span className="mono green-text">{money(item.balance)}</span><div className="balance-adjust"><input type="number" value={amounts[item.id] || ''} onChange={event => setAmounts(old => ({ ...old, [item.id]: event.target.value }))} placeholder="+ / -" /><button onClick={() => { adjustUser(item.id, Number(amounts[item.id])); setAmounts(old => ({ ...old, [item.id]: '' })); }}><Save className="h-4 w-4" /></button></div></div>)}</div> : <Empty icon={Users} text="لا يوجد مستخدمون مسجلون بعد." />}</div>;
}

  function AdminSettingsPage() {
   const { settings, saveSettings, saveWhatsAppMeta } = useArena(); const [form, setForm] = useState(settings); const [metaToken, setMetaToken] = useState(''); const [saved, setSaved] = useState(false); const [error, setError] = useState(''); const whatsappMode = form.whatsapp_mode || 'link'; const update = (key: string, value: string) => setForm(old => ({ ...old, [key]: value })); const toggleMode = (mode: 'link' | 'meta') => update('whatsapp_mode', whatsappMode === mode ? 'off' : mode); const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); const patch = { ...form, whatsapp_mode: whatsappMode, whatsapp_direct_link: form.whatsapp_direct_link || DEFAULT_ADMIN_WHATSAPP_LINK }; if (whatsappMode === 'meta' && metaToken.trim()) { const okay = await saveWhatsAppMeta(metaToken, form.whatsapp_meta_phone_number_id || ''); if (!okay) { setError('تعذر حفظ إعدادات Meta. تأكد من تسجيل دخول الإدارة ورقم Phone Number ID.'); return; } setMetaToken(''); } saveSettings(patch); setSaved(true); setTimeout(() => setSaved(false), 1800); }; return <div className="admin-page"><AdminSectionHeader icon={Settings} title="إعدادات المنصة" subtitle="حدّث بيانات الدفع ونسبة العمولة ومعلومات التواصل." /><form className="settings-form panel-card" onSubmit={submit}>{saved && <Notice>تم حفظ الإعدادات بنجاح.</Notice>}{error && <Notice type="error">{error}</Notice>}<div className="settings-section"><h3>بيانات التحويل البنكي</h3><div className="form-grid"><Field label="اسم المستفيد" value={form.cih_name || ''} onChange={value => update('cih_name', value)} /><Field label="رقم الحساب / RIB" value={form.cih_rib || ''} onChange={value => update('cih_rib', value)} /></div></div><div className="settings-section"><h3>بيانات Cash Plus</h3><div className="form-grid"><Field label="اسم المستفيد" value={form.cashplus_name || ''} onChange={value => update('cashplus_name', value)} /><Field label="رقم التعريف" value={form.cashplus_cin || ''} onChange={value => update('cashplus_cin', value)} /></div></div><div className="settings-section"><h3>الإدارة والتسعير</h3><div className="form-grid"><Field label="نسبة العمولة" value={form.commission_rate || '0.10'} onChange={value => update('commission_rate', value)} /><Field label="مبالغ الشحن السريعة" value={form.recharge_amounts || '20,50,100,200,500'} onChange={value => update('recharge_amounts', value)} /></div><small className="settings-hint">اكتب المبالغ مفصولة بفواصل، مثل: 20,50,100,200,500</small></div><div className="settings-section whatsapp-settings"><div className="settings-section-heading"><div><h3>ربط الموقع مع WhatsApp</h3><small>اختر طريقة واحدة فقط لتجنب تكرار الإشعارات.</small></div><span className={`whatsapp-status ${whatsappMode === 'off' ? 'is-off' : 'is-on'}`}>{whatsappMode === 'off' ? 'متوقف' : whatsappMode === 'meta' ? 'Meta API' : 'رابط مباشر'}</span></div><div className="whatsapp-methods"><div className={`whatsapp-method ${whatsappMode === 'link' ? 'is-active' : ''}`}><div className="whatsapp-method-top"><div><strong>الرابط المباشر</strong><small>يفتح حساب الإدارة برسالة جاهزة، ثم تضغط الإدارة إرسال.</small></div><button type="button" className={whatsappMode === 'link' ? 'danger-button small' : 'primary-button small'} onClick={() => toggleMode('link')}>{whatsappMode === 'link' ? 'إلغاء التفعيل' : 'تفعيل'}</button></div><Field label="رابط حساب الإدارة" value={form.whatsapp_direct_link || DEFAULT_ADMIN_WHATSAPP_LINK} onChange={value => update('whatsapp_direct_link', value)} placeholder="https://wa.me/212..." /></div><div className={`whatsapp-method ${whatsappMode === 'meta' ? 'is-active' : ''}`}><div className="whatsapp-method-top"><div><strong>Meta WhatsApp API</strong><small>إرسال تلقائي من الخادم دون فتح WhatsApp عند المستخدم.</small></div><button type="button" className={whatsappMode === 'meta' ? 'danger-button small' : 'primary-button small'} onClick={() => toggleMode('meta')}>{whatsappMode === 'meta' ? 'إلغاء التفعيل' : 'تفعيل'}</button></div>{whatsappMode === 'meta' && <div className="form-grid"><label className="form-field"><span>Access Token</span><input type="password" value={metaToken} onChange={event => setMetaToken(event.target.value)} placeholder="اتركه فارغاً إذا كان محفوظاً" /></label><Field label="Phone Number ID" value={form.whatsapp_meta_phone_number_id || ''} onChange={value => update('whatsapp_meta_phone_number_id', value)} placeholder="مثال: 1320184641179179" /></div>}</div></div></div><button className="primary-button"><Save className="h-4 w-4" />حفظ التغييرات</button></form></div>; }

 function FeaturedMatchesSettings() {
   const { settings, saveSettings } = useArena(); const [items, setItems] = useState<FeaturedMatch[]>(() => readFeaturedMatches(settings)); const [editingId, setEditingId] = useState<string | null>(null); const [draft, setDraft] = useState<FeaturedMatch>(() => readFeaturedMatches(settings)[0] || newFeaturedMatch()); const [saved, setSaved] = useState(false);
   const update = (key: keyof FeaturedMatch, value: string | number | boolean) => setDraft(old => ({ ...old, [key]: value }));
   const persist = (next: FeaturedMatch[]) => { setItems(next); saveSettings({ featured_matches: JSON.stringify(next) }); setSaved(true); setTimeout(() => setSaved(false), 1800); };
   const save = (event: FormEvent) => { event.preventDefault(); const nextItem = { ...draft, title: draft.title.trim(), creatorName: draft.creatorName.trim(), opponentName: draft.opponentName.trim(), note: draft.note.trim(), prize: Number(draft.prize) || 0, id: editingId || `featured-${Date.now()}` }; const next = editingId ? items.map(item => item.id === editingId ? nextItem : item) : [...items, nextItem]; persist(nextItem.active ? next.map(item => ({ ...item, active: item.id === nextItem.id })) : next); setEditingId(null); setDraft(newFeaturedMatch()); };
   const edit = (item: FeaturedMatch) => { setEditingId(item.id); setDraft(item); };
   const remove = (id: string) => { const next = items.filter(item => item.id !== id); const normalized = next.length && !next.some(item => item.active) ? next.map((item, index) => ({ ...item, active: index === 0 })) : next; persist(normalized); if (editingId === id) { setEditingId(null); setDraft(newFeaturedMatch()); } };
   const activate = (id: string) => persist(items.map(item => ({ ...item, active: item.id === id })));
   return <section className="settings-form panel-card featured-settings"><div className="settings-section"><div className="settings-section-heading"><div><h3>مواجهات الصفحة الرئيسية</h3><small>أضف أو عدّل أو احذف مواجهة الليلة، واختر المواجهة الظاهرة للزوار.</small></div><span className="featured-settings-badge"><Radio className="h-3.5 w-3.5" /> مباشر</span></div>{saved && <Notice>تم حفظ مواجهات الصفحة الرئيسية.</Notice>}<div className="featured-admin-layout"><form className="featured-editor form-stack" onSubmit={save}><div className="featured-editor-title"><strong>{editingId ? 'تعديل المواجهة' : 'إضافة مواجهة جديدة'}</strong>{editingId && <button type="button" className="text-link" onClick={() => { setEditingId(null); setDraft(newFeaturedMatch()); }}>إلغاء التعديل</button>}</div><Field label="عنوان المواجهة" value={draft.title} onChange={value => update('title', value)} /><div className="form-grid"><Field label="اسم اللاعب الأول" value={draft.creatorName} onChange={value => update('creatorName', value)} /><Field label="الاختصار" value={draft.creatorShort} onChange={value => update('creatorShort', value)} /></div><div className="form-grid"><label className="form-field"><span>نادي اللاعب الأول</span><select value={draft.creatorTeam} onChange={event => update('creatorTeam', event.target.value)}>{TEAM_OPTIONS.map(team => <option value={team.id} key={team.id}>{team.name}</option>)}</select></label><div className="featured-team-preview"><TeamLogo teamId={draft.creatorTeam} large /></div></div><div className="form-grid"><Field label="اسم اللاعب الثاني" value={draft.opponentName} onChange={value => update('opponentName', value)} /><Field label="الاختصار" value={draft.opponentShort} onChange={value => update('opponentShort', value)} /></div><div className="form-grid"><label className="form-field"><span>نادي اللاعب الثاني</span><select value={draft.opponentTeam} onChange={event => update('opponentTeam', event.target.value)}>{TEAM_OPTIONS.map(team => <option value={team.id} key={team.id}>{team.name}</option>)}</select></label><div className="featured-team-preview"><TeamLogo teamId={draft.opponentTeam} large /></div></div><div className="form-grid"><Field label="الجائزة ($)" type="number" value={String(draft.prize)} onChange={value => update('prize', Number(value))} /><Field label="العبارة أسفل المواجهة" value={draft.note} onChange={value => update('note', value)} /></div><label className="check-field"><input type="checkbox" checked={draft.active} onChange={event => update('active', event.target.checked)} /> عرض هذه المواجهة في الصفحة الرئيسية</label><button className="primary-button" type="submit"><Save className="h-4 w-4" />{editingId ? 'حفظ التعديل' : 'إضافة المواجهة'}</button></form><div className="featured-admin-list">{items.length ? items.map(item => <article className={`featured-admin-card ${item.active ? 'is-active' : ''}`} key={item.id}><div className="featured-admin-card-head"><span className="featured-live-label">{item.active ? 'ظاهرة الآن' : 'مخفية'}</span><span className="status-badge status-info">{money(item.prize)}</span></div><div className="featured-match-mini"><TeamLogo teamId={item.creatorTeam} /><span><strong>{item.creatorName}</strong><small>{item.title}</small></span><b>VS</b><span><strong>{item.opponentName}</strong><small>{teamById(item.opponentTeam)?.name || 'فريق'}</small></span><TeamLogo teamId={item.opponentTeam} /></div><div className="request-actions"><button type="button" className="secondary-button small" onClick={() => edit(item)}><Pencil className="h-3.5 w-3.5" />تعديل</button>{!item.active && <button type="button" className="secondary-button small" onClick={() => activate(item.id)}>إظهار</button>}<button type="button" className="danger-button small" onClick={() => remove(item.id)}><Trash2 className="h-3.5 w-3.5" />حذف</button></div></article>) : <Empty icon={Radio} text="لا توجد مواجهة مميزة. أضف أول مواجهة من النموذج." />}</div></div></div></section>;
 }

 function OnlineCountSettings() {
  const { settings, saveSettings, users, players } = useArena(); const [mode, setMode] = useState(settings.online_count_mode || 'auto'); const [manual, setManual] = useState(settings.online_count_manual || '25'); const [saved, setSaved] = useState(false);
  const realUsers = Math.max(users.length, players.length);
  const manualNumber = Number(manual) || 0;
  const implausible = mode === 'manual' && manualNumber > realUsers * 5 && manualNumber > 10;
  const submit = (event: FormEvent) => { event.preventDefault(); saveSettings({ online_count_mode: mode, online_count_manual: manual }); setSaved(true); setTimeout(() => setSaved(false), 1800); };
  return <section className="settings-form panel-card online-count-settings"><div className="settings-section"><h3>عداد المتصلين في الصفحة الرئيسية</h3><p className="settings-help">اختر بين العدد الحقيقي للمستخدمين المتصلين أو رقم يدوي للعرض.</p>{saved && <Notice>تم حفظ إعدادات المتصلين.</Notice>}<form className="form-stack" onSubmit={submit}><div className="filter-list"><button type="button" className={mode === 'auto' ? 'filter-active' : ''} onClick={() => setMode('auto')}>تلقائي: المتصلون الحقيقيون</button><button type="button" className={mode === 'manual' ? 'filter-active' : ''} onClick={() => setMode('manual')}>يدوي: رقم ثابت</button></div>{mode === 'manual' && <Field label="الرقم الظاهر" type="number" value={manual} onChange={setManual} />}{implausible && <Notice type="error">الرقم الظاهر ({manualNumber}) أكبر بكثير من عدد الحسابات المسجلة فعلياً ({realUsers}). الأرقام المبالغ فيها تُضعف ثقة اللاعبين وتبدو مكشوفة بجانب عدد المباريات المتاحة.</Notice>}{mode === 'auto' && <small className="settings-hint">يُحسب العدد من جلسات المستخدمين المتصلة فعلياً حالياً.</small>}<button className="primary-button" type="submit"><Save className="h-4 w-4" />حفظ إعدادات العداد</button></form></div></section>;
}

function AdminUsersDetailsPage() {
  const { users, adjustUser, setUserBanned } = useArena(); const [query, setQuery] = useState(''); const [selectedId, setSelectedId] = useState<string | null>(null); const [amounts, setAmounts] = useState<Record<string, string>>({}); const [banReason, setBanReason] = useState(''); const rows = users.filter(item => !query || `${item.username} ${item.email} ${item.efootball_id} ${item.whatsapp}`.toLowerCase().includes(query.toLowerCase())); const selected = users.find(item => item.id === selectedId);
  const change = (id: string, amount: number) => { if (!amount) return; adjustUser(id, amount); setAmounts(old => ({ ...old, [id]: '' })); };
  return <div className="admin-page"><AdminSectionHeader icon={Users} title="حسابات المستخدمين" subtitle="معلومات كاملة عن الحسابات، مع التحكم في الحالة وإدارة الرصيد." /><div className="account-toolbar"><div className="search-box"><Search className="h-4 w-4" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="ابحث بالاسم أو البريد أو المعرّف" /></div><span className="records-count">{rows.length} حساب</span></div>{rows.length ? <div className="users-layout"><div className="user-list detailed">{rows.map(item => <article className={`user-detail-card ${item.banned ? 'is-banned' : ''}`} key={item.id} onClick={() => setSelectedId(item.id)}><div className="user-card-head"><span className="avatar">{initials(item.username)}</span><span className="user-admin-main"><strong>{item.username}</strong><small>{item.email}</small></span><span className={item.banned ? 'ban-label' : 'active-label'}>{item.banned ? 'محظور' : 'نشط'}</span></div><div className="user-facts"><span><small>eFootball ID</small><b className="mono">{item.efootball_id}</b></span><span><small>واتساب</small><b className="mono">{item.whatsapp || 'غير مضاف'}</b></span><span><small>الرصيد</small><b className="green-text">{money(item.balance)}</b></span><span><small>النتائج</small><b>{item.wins} فوز / {item.losses} خسارة</b></span></div><div className="user-card-footer"><span>آخر دخول: {item.last_login ? date(item.last_login) : 'لم يسجل الدخول بعد'}</span><button className="text-link" onClick={event => { event.stopPropagation(); setSelectedId(item.id); }}>عرض التفاصيل <ArrowLeft className="h-3.5 w-3.5" /></button></div></article>)}</div>{selected && <aside className="account-drawer"><div className="drawer-heading"><span><span className="avatar large">{initials(selected.username)}</span><span><h3>{selected.username}</h3><small>{selected.email}</small></span></span><button className="icon-button" onClick={() => setSelectedId(null)} aria-label="إغلاق"><X className="h-4 w-4" /></button></div><div className="account-status"><span className={selected.banned ? 'ban-label' : 'active-label'}>{selected.banned ? 'الحساب محظور' : 'الحساب نشط'}</span><strong>{money(selected.balance)}</strong></div><div className="account-info-grid"><span><small>المعرّف الداخلي</small><b className="mono">{selected.id}</b></span><span><small>eFootball ID</small><b className="mono">{selected.efootball_id}</b></span><span><small>واتساب</small><b className="mono">{selected.whatsapp || 'غير مضاف'}</b></span><span><small>تاريخ التسجيل</small><b>{selected.created_at ? date(selected.created_at) : 'غير متوفر'}</b></span><span><small>آخر دخول</small><b>{selected.last_login ? date(selected.last_login) : 'لم يسجل الدخول'}</b></span><span><small>السجل الرياضي</small><b>{selected.wins} فوز / {selected.losses} خسارة</b></span></div><div className="balance-control"><h4>إدارة الرصيد</h4><p>يمكنك استخدام قيمة موجبة للإضافة أو سالبة للخصم.</p><div className="quick-amounts"><button onClick={() => change(selected.id, 10)}>+10</button><button onClick={() => change(selected.id, 50)}>+50</button><button onClick={() => change(selected.id, 100)}>+100</button></div><div className="balance-adjust large"><input type="number" value={amounts[selected.id] || ''} onChange={event => setAmounts(old => ({ ...old, [selected.id]: event.target.value }))} placeholder="مثال: 50 أو -20" /><button className="primary-button small" onClick={() => change(selected.id, Number(amounts[selected.id]))}><Save className="h-4 w-4" />تطبيق</button></div></div><div className="ban-control"><h4>{selected.banned ? 'إلغاء حظر الحساب' : 'حظر الحساب'}</h4>{selected.banned && selected.ban_reason && <p className="ban-reason">سبب الحظر: {selected.ban_reason}</p>}{!selected.banned && <textarea rows={2} value={banReason} onChange={event => setBanReason(event.target.value)} placeholder="سبب الحظر (اختياري)" />}{selected.banned ? <button className="primary-button full" onClick={() => { setUserBanned(selected.id, false, ''); setBanReason(''); }}><CheckCircle2 className="h-4 w-4" />إلغاء الحظر والسماح بالدخول</button> : <button className="danger-button full" onClick={() => { setUserBanned(selected.id, true, banReason); setBanReason(''); }}><ShieldAlert className="h-4 w-4" />حظر الحساب</button>}</div></aside>}</div> : <Empty icon={Users} text="لا يوجد مستخدمون مسجلون بعد." />}</div>;
}

function MomentumPage() {
  const { players, matches, tournaments } = useArena();
  const liveMatches = matches.filter(item => item.status === 'PLAYING').length;
  const activityScore = Math.min(98, 58 + matches.filter(item => item.status === 'OPEN').length * 4 + tournaments.length * 3);
   const rankedPlayers = rankPlayers(players); return <div className="shell page-wrap"><div className="page-header"><PageTitle icon={Zap} title="نبض الساحة" subtitle="لقطة حيّة عن اللاعبين والمواجهات التي تستحق المتابعة الآن." /><span className="status-badge status-success"><span className="online-dot" /> نشط الآن</span></div><div className="pulse-layout"><section className="panel-card"><div className="panel-heading"><span><BarChart3 className="h-4 w-4" />أفضل اللاعبين هذا الأسبوع</span><small>حسب نسبة الفوز</small></div><div className="pulse-list">{rankedPlayers.slice(0, 5).map((player, index) => <div className="pulse-row" key={player.id}><span className={`rank rank-${index + 1}`}>{index + 1}</span><span className="avatar">{initials(player.username)}</span><span className="pulse-player"><strong>{player.username}</strong><small>{player.wins} فوز • {player.efootball_id}</small></span><b className="green-text">{player.win_rate}%</b></div>)}</div></section><aside className="panel-card pulse-meter"><div className="panel-heading"><span><Activity className="h-4 w-4" />مؤشر الساحة</span><small>يتجدد باستمرار</small></div><strong>{activityScore}<small>/100</small></strong><div className="meter-track"><span style={{ width: `${activityScore}%` }} /></div><p>هناك {liveMatches} مباراة جارية و{matches.filter(item => item.status === 'OPEN').length} تحديات تنتظر منافساً.</p><div className="pulse-facts"><span><b>{players.length + 17}</b> لاعب في المنافسة</span><span><b>{tournaments.length + 8}</b> بطولات قادمة</span></div></aside></div><section className="panel-card pulse-callout"><div><span className="eyebrow"><span className="pulse-dot" />تحدٍّ مقترح</span><h2>الوقت مناسب لصناعة سلسلة انتصارات.</h2><p>ابدأ بمباراة قصيرة، ارفع تقييمك، ثم ادخل البطولة التالية بثقة.</p></div><Link href="/matches" className="primary-button">استكشف التحديات <ArrowLeft className="h-4 w-4" /></Link></section></div>;
}
function NotificationDropdown({ open, onClose, onOpenAll }: { open: boolean; onClose: () => void; onOpenAll: () => void }) {
  const { user, notifications, markNotificationRead } = useArena();
  const [, setLocation] = useLocation();
  if (!open || !user) return null;
  const mine = notifications.filter(item => item.user_id === user.id).slice(0, 6);
  const unread = mine.filter(item => !item.read_at).length;
  const open1 = (id: string, link?: string) => { markNotificationRead(id); onClose(); if (link) setLocation(link); };
  return <div className="notification-dropdown" role="menu" aria-label="الإشعارات"><div className="notification-dropdown-head"><span><Bell className="h-4 w-4" />الإشعارات{unread > 0 && <b>{unread} جديد</b>}</span>{mine.length > 0 && <button type="button" onClick={onOpenAll}>عرض الكل</button>}</div>{mine.length ? <div className="notification-dropdown-list">{mine.map(item => <button type="button" className={`notification-item ${item.read_at ? '' : 'is-unread'}`} key={item.id} onClick={() => open1(item.id, item.link)}><span className="notification-item-title">{item.title}{!item.read_at && <i className="notification-unread-dot" />}</span><small className="notification-item-body">{item.body}</small><span className="notification-item-time">{date(item.created_at)}</span></button>)}</div> : <div className="notification-dropdown-empty"><Bell className="h-5 w-5" /><span>لا توجد إشعارات بعد.</span><small>ستظهر هنا تحديثات مبارياتك وطلباتك.</small></div>}</div>;
}
