  const whatsappHref = `${whatsappLink}${whatsappLink.includes('?') ? '&' : '?'}text=${encodeURIComponent('مرحباً، أحتاج مساعدة من فريق ARENA//X.')}`;
  const submit = async (event: FormEvent) => { event.preventDefault(); const ok = await createSupportTicket(subject, category, message); setFeedback(ok ? 'تم فتح تذكرة الدعم.' : 'تعذر فتح التذكرة. تحقق من البيانات.'); if (ok) { setSubject(''); setMessage(''); } };
