function RateMatchPage() {
  const { id } = useParams<{ id: string }>(); const { user, matches, submitRating } = useArena(); const [, setLocation] = useLocation(); const match = matches.find(item => item.id === id); const [score, setScore] = useState('5'); const [comment, setComment] = useState(''); const [feedback, setFeedback] = useState('');
  if (!user || !match || match.status !== 'COMPLETED') return <div className="shell page-wrap"><Empty icon={CheckCircle2} text="التقييم متاح بعد اكتمال المباراة وتسجيل الدخول." /><Link href="/matches" className="primary-button">العودة إلى المباريات</Link></div>;
  const revieweeId = user.id === match.creator_id ? match.opponent_id : match.creator_id; const submit = async (event: FormEvent) => { event.preventDefault(); if (!revieweeId) return; const ok = await submitRating(match.id, revieweeId, Number(score), comment); setFeedback(ok ? 'تم تسجيل تقييمك.' : 'تعذر تسجيل التقييم. ربما تم التقييم مسبقاً.'); if (ok) setTimeout(() => setLocation(`/matches/${match.id}`), 800); };
  return <div className="shell page-wrap"><PageTitle icon={CheckCircle2} title="تقييم المنافس" subtitle="ساعد اللاعبين على بناء سمعة موثوقة." /><form className="panel-card form-stack" onSubmit={submit}>{feedback && <Notice type={feedback.startsWith('تم') ? 'success' : 'error'}>{feedback}</Notice>}<label className="form-field"><span>التقييم</span><select value={score} onChange={event => setScore(event.target.value)}><option value="5">5 / ممتاز</option><option value="4">4 / جيد جداً</option><option value="3">3 / جيد</option><option value="2">2 / يحتاج تحسين</option><option value="1">1 / سيئ</option></select></label><label className="form-field"><span>تعليق اختياري</span><textarea rows={4} value={comment} onChange={event => setComment(event.target.value)} placeholder="اكتب تعليقاً محترماً عن التجربة" /></label><button className="primary-button">حفظ التقييم</button></form></div>;
}

type MatchPhase = 'ROOM_SETUP' | 'ROOM_READY' | 'PLAYING' | 'REVIEW';
const matchPhase = (match: Match, now: number): MatchPhase => {
  if (['COMPLETED', 'DISPUTE'].includes(match.status)) return 'REVIEW';
  if (match.status !== 'PLAYING') return 'ROOM_SETUP';
  if (!match.room_code) {
    const deadline = match.room_setup_deadline_at ? new Date(match.room_setup_deadline_at).getTime() : 0;
    return deadline && deadline <= now ? 'REVIEW' : 'ROOM_SETUP';
  }
  if (!match.match_deadline_at) return 'ROOM_READY';
  return new Date(match.match_deadline_at).getTime() <= now ? 'REVIEW' : 'PLAYING';
};
const formatCountdown = (seconds: number) => `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;
function MatchLifecycleOverlay({ match }: { match: Match }) {
  const { user, confirmRoomCopied, finishMatch } = useArena(); const [now, setNow] = useState(Date.now()); const [feedback, setFeedback] = useState('');
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => window.clearInterval(timer); }, []);
  const phase = matchPhase(match, now); const participant = Boolean(user && [match.creator_id, match.opponent_id].includes(user.id));
  useEffect(() => { if (participant && match.status === 'PLAYING' && phase === 'REVIEW') void finishMatch(match.id); }, [finishMatch, match.id, match.status, participant, phase]);
  if (!participant || match.status !== 'PLAYING') return null;
  const fallbackSetupDeadline = match.started_at ? new Date(new Date(match.started_at).getTime() + 60 * 1000).getTime() : now + 60 * 1000;
  const deadline = phase === 'ROOM_SETUP' ? (match.room_setup_deadline_at ? new Date(match.room_setup_deadline_at).getTime() : fallbackSetupDeadline) : (match.match_deadline_at ? new Date(match.match_deadline_at).getTime() : now);
  const seconds = Math.max(0, Math.ceil((deadline - now) / 1000));
  const copyRoom = async () => { try { await navigator.clipboard?.writeText(match.room_code || ''); } catch { /* Clipboard permission is optional. */ } const ok = await confirmRoomCopied(match.id); setFeedback(ok ? 'تم تسجيل نسخ الغرفة. ينتظر النظام تأكيد اللاعب الآخر.' : 'تعذر تأكيد نسخ الغرفة.'); };
  if (phase === 'ROOM_SETUP') return <section className="match-lifecycle room-setup"><span className="lifecycle-spinner"><RefreshCw className="h-7 w-7" /></span><div><strong>جاري إنشاء الغرفة</strong><small>تجهّز الإدارة مباراة عادلة للاعبين</small></div><b className="lifecycle-countdown">{formatCountdown(seconds)}</b></section>;
  if (phase === 'ROOM_READY') return <section className="match-lifecycle room-ready"><div><strong>أيدي الغرفة جاهز</strong><small>انسخ الأيدي وأدخل الغرفة. يبدأ عداد اللعب بعد نسخ اللاعب الثاني.</small></div><div className="lifecycle-room-code"><b>{match.room_code}</b><button className="secondary-button small" onClick={() => void copyRoom()}><Copy className="h-4 w-4" />نسخ الأيدي</button></div>{feedback && <small className="green-text">{feedback}</small>}</section>;
  if (phase === 'PLAYING') return <section className="match-lifecycle game-running"><div><strong>المباراة جارية</strong><small>ينتهي الوقت وتنتقل المباراة للمراجعة عند وصول العداد إلى صفر.</small></div><b className="lifecycle-countdown">{formatCountdown(seconds)}</b><button className="primary-button small" onClick={() => void finishMatch(match.id)}><CheckCircle2 className="h-4 w-4" />انتهت المباراة</button></section>;
  return null;
}

function MatchDetailRoute() {
  const { id } = useParams<{ id: string }>();
  const { user, matches } = useArena();
  const match = matches.find(item => item.id === id);
  const canCancel = !!user && !!match && user.id === match.creator_id && match.status === 'OPEN';
  return <>{match && <MatchLifecycleOverlay match={match} />}<MatchDetailPageV2 />{canCancel && <div className="shell page-wrap"><section className="panel-card"><CancelMatchControl match={match} /></section></div>}</>;
}

function NotFound() { return <div className="shell page-wrap"><Empty icon={AlertCircle} text="الصفحة التي تبحث عنها غير موجودة." /><Link href="/store" className="primary-button">العودة إلى المتجر</Link></div>; }
  function AppShell() { return <ArenaProvider><SiteMeta /><a className="skip-link" href="#main-content">تخطي إلى المحتوى</a><PublicNavbar /><main id="main-content" className="main-content"><Switch><Route path="/" component={HomePage} /><Route path="/store/accounts/:id" component={StoreAccountDetailPage} /><Route path="/store/recharge" component={StoreRechargePage} /><Route path="/live" component={StoreLivePage} /><Route path="/store" component={StorePage} /><Route path="/arena" component={HomePage} /><Route path="/matches/:id" component={MatchDetailRoute} /><Route path="/matches" component={MatchesPage} /><Route path="/tournaments" component={TournamentsPage} /><Route path="/leaderboard" component={LeaderboardPage} /><Route path="/momentum" component={MomentumPage} /><Route path="/orders" component={StoreOrdersPage} /><Route path="/notifications" component={NotificationsPage} /><Route path="/support" component={SupportPage} /><Route path="/rate/:id" component={RateMatchPage} /><Route path="/terms"><LegalPage kind="terms" /></Route><Route path="/privacy"><LegalPage kind="privacy" /></Route><Route path="/rules"><LegalPage kind="rules" /></Route><Route path="/profile" component={ProfilePage} /><Route path="/verify" component={AccountVerificationPage} /><Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route><Route path="/admin/:section" component={AdminPage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch></main><Footer /></ArenaProvider>; }
export default AppShell;
